                        }
                        
                    } catch (error) {
                        console.error('Error updating price breakdown:', error);
                    }
                }
                
                // Reset save button to original state
                function resetSaveButton() {
                    const saveBtn = document.getElementById('savePackageBtn');
                    if (saveBtn) {
                        saveBtn.disabled = false;
                        saveBtn.innerHTML = '<i class="ri-save-line me-2"></i>Save Tour Package';
                    }
                }
                
                // Handle save package button click - show loader and disable
                async function handleSavePackage(button) {
                    // Disable button
                    button.disabled = true;
                    
                    // Show loader and update text
                    button.innerHTML = '<span class="spinner-border spinner-border-sm me-2" role="status" aria-hidden="true"></span>Saving...';
                    
                    // Call the actual save function
                    const result = await saveAllBookings();
                    
                    // If save failed or returned false, reset button
                    if (result === false) {
                        resetSaveButton();
                    }
                }

                async function saveAllBookings() {
                    
                    // ==========================================
                    // STEP 1: CREATE TOUR (if not already created)
                    // ==========================================
                    
                    const agentId = document.getElementById('agent_id').value;
                    let tourId = window.currentTourId;

                    // If tour doesn't exist, create it first
                    if (!tourId) {
                        console.log('Tour not created yet, creating tour first...');
                        
                        // Validation for tour creation
                        const country = document.getElementById('user_country').value;
                        const startDate = document.getElementById('start_date').value;
                        const endDate = document.getElementById('end_date').value;
                        const agent = document.getElementById('agent_id').value;
                        const enquiry = @json($enquiry);

                        if (!country || !startDate || !endDate || !agent) {
                            alert('Please fill in all required fields (Country, Travel Dates, Agent, and Guests) before saving the tour package.');
                            resetSaveButton();
                            return false;
                        }

                        // Additional validation for guests
                        const adults = parseInt(document.getElementById('adults').value) || 0;
                        const male = parseInt(document.getElementById('male').value) || 0;
                        const female = parseInt(document.getElementById('female').value) || 0;
                        let children = parseInt(document.getElementById('children').value) || 0;
                        const infants = parseInt(document.getElementById('infants').value) || 0;
                        const childAgesData = document.getElementById('child_ages').value;
                        let childAges = [];

                        // Handle child ages validation for both scenarios
                        if(enquiry && enquiry.child_ages){
                            if (typeof enquiry.child_ages === 'string') {
                                childAges = enquiry.child_ages.split(',')
                                    .map(age => age.trim())
                                    .filter(age => age !== "");
                            } else if (Array.isArray(enquiry.child_ages)) {
                                childAges = enquiry.child_ages;
                            }
                            
                            children = enquiry.child || children;
                            
                            if(childAges.length !== children){
                                alert('Please select ages for all children in the guest selector.');
                                return false;
                            }
                        } else if (children > 0) {
                            try {
                                if (childAgesData) {
                                    childAges = JSON.parse(childAgesData);
                                } else {
                                    childAges = [];
                                }
                                
                                if (childAges.length !== children) {
                                    alert('Please select ages for all children in the guest selector.');
                                    return false;
                                }
                            } catch (e) {
                                console.error('Error parsing child ages data:', e);
                                alert('Invalid child ages data. Please reselect children ages.');
                                return false;
                            }
                        }
                        
                        if (adults < 1) {
                            alert('At least 1 adult is required for the tour package.');
                            return false;
                        }
                        
                        if ((male + female) !== adults) {
                            alert('Total male and female count must equal total adults.');
                            return false;
                        }
                        
                        // Collect main guest data
                        const mainGuestData = {
                            full_name: document.getElementById('customerFullName')?.value || '',
                            email: document.getElementById('customerEmail')?.value || '',
                            country_code: document.getElementById('customerCountryCode')?.value || '',
                            phone: document.getElementById('customerPhone')?.value || '',
                            address1: document.getElementById('customerAddress1')?.value || '',
                            address2: document.getElementById('customerAddress2')?.value || '',
                            state: document.getElementById('customerState')?.value || '',
                            zip: document.getElementById('customerZip')?.value || '',
                            special_requests: document.getElementById('customerSpecialRequests')?.value || ''
                        };

                        // Collect additional guests data
                        const additionalGuests = [];
                        const guestCards = document.querySelectorAll('.guest-card');
                        guestCards.forEach((card) => {
                            const inputs = card.querySelectorAll('input, select');
                            const guestData = {};
                            inputs.forEach(input => {
                                const name = input.getAttribute('name');
                                if (name && name.includes('additional_guests')) {
                                    const fieldName = name.match(/\[(\d+)\]\[(\w+)\]/);
                                    if (fieldName) {
                                        const fieldKey = fieldName[2];
                                        guestData[fieldKey] = input.value || '';
                                    }
                                }
                            });
                            if (Object.keys(guestData).length > 0) {
                                additionalGuests.push(guestData);
                            }
                        });

                        // Prepare form data for tour creation
                        const tourFormData = new FormData();
                        tourFormData.append('_token', document.querySelector('input[name="_token"]').value);
                        tourFormData.append('user_country', country);
                        tourFormData.append('start_date', startDate);
                        tourFormData.append('end_date', endDate);
                        tourFormData.append('adults', adults);
                        tourFormData.append('male', male);
                        tourFormData.append('female', female);
                        tourFormData.append('children', children);
                        tourFormData.append('infants', infants);
                        tourFormData.append('child_ages', childAgesData);
                        tourFormData.append('agent_id', agent);
                        tourFormData.append('enquiry_id', enquiry?enquiry.enquiry_id:0);
                        tourFormData.append('mainguest', JSON.stringify(mainGuestData));
                        tourFormData.append('additionalguest', JSON.stringify(additionalGuests));
                        
                        // Send AJAX request to create tour
                        try {
                            const tourResponse = await fetch('{{ route('single-tour-package.store') }}', {
                                method: 'POST',
                                headers: {
                                    'X-Requested-With': 'XMLHttpRequest',
                                    'Accept': 'application/json',
                                },
                                body: tourFormData
                            });
                            
                            if (!tourResponse.ok) {
                                const errorData = await tourResponse.json();
                                throw new Error(errorData.error || 'Failed to create tour');
                            }
                            
                            const tourData = await tourResponse.json();
                            
                            if (tourData.success) {
                                console.log('✅ Tour created successfully:', tourData);
                                
                                // Set tour dates for hotel section
                                tourStartDate = startDate;
                                tourEndDate = endDate;
                                
                                // Store tour info globally
                                window.currentTourId = tourData.tour_id;
                                window.currentDisplayId = tourData.display_id;
                                tourId = tourData.tour_id; // Update local variable
                                
                                showNotification('Tour created successfully! Tour ID: ' + tourData.display_id, 'success');
                            } else {
                                alert('Failed to create tour: ' + (tourData.message || 'Unknown error'));
                                return false;
                            }
                        } catch (error) {
                            console.error('Error creating tour:', error);
                            alert('Error creating tour: ' + error.message);
                            return false;
                        }
                    }

                    // ==========================================
                    // STEP 2: SAVE ALL SERVICE BOOKINGS
                    // ==========================================
                    
                    // Validate service selections (time slots, meal types)
                    if (!validateServiceSelections()) {
                        return false;
                    }

                    // Manually calculate guide pricing before updating data fields
                    calculateAllGuidePricing();
                    
                    // Update all service data fields before sending
                    updateHotelDataField();
                    updateAttractionDataField();
                    updateGuideDataField();
                    updateRestaurantDataField();
                    updateTransportDataField();

                    // Debug: Log transport data after collection
                    console.log('=== TRANSPORT DATA DEBUG AFTER COLLECTION ===');
                    const transportDataDebug = document.getElementById('transport_data')?.value;
                    const entryPortDataDebug = document.getElementById('entry_port_data')?.value;
                    const exitPortDataDebug = document.getElementById('exit_port_data')?.value;
                    
                    console.log('Transport data field:', transportDataDebug);
                    console.log('Entry port data field:', entryPortDataDebug);
                    console.log('Exit port data field:', exitPortDataDebug);
                    
                    // Parse and log the actual data
                    if (transportDataDebug) {
                        try {
                            const parsedTransportData = JSON.parse(transportDataDebug);
                            console.log('Parsed transport data:', parsedTransportData);
                            console.log('Number of transport items:', parsedTransportData.length);
                        } catch (error) {
                            console.error('Error parsing transport data:', error);
                        }
                    }
                    
                    if (entryPortDataDebug) {
                        try {
                            const parsedEntryData = JSON.parse(entryPortDataDebug);
                            console.log('Parsed entry port data:', parsedEntryData);
                            console.log('Number of entry port items:', parsedEntryData.length);
                        } catch (error) {
                            console.error('Error parsing entry port data:', error);
                        }
                    }
                    
                    if (exitPortDataDebug) {
                        try {
                            const parsedExitData = JSON.parse(exitPortDataDebug);
                            console.log('Parsed exit port data:', parsedExitData);
                            console.log('Number of exit port items:', parsedExitData.length);
                        } catch (error) {
                            console.error('Error parsing exit port data:', error);
                        }
                    }
                    
                    // Get all service data from hidden fields (with null checks)
                    const hotelData = document.getElementById('hotel_data')?.value || '';
                    const attractionData = document.getElementById('attraction_data')?.value || '';
                    const restaurantData = document.getElementById('restaurant_data')?.value || '';
                    const guideData = document.getElementById('guide_data')?.value || '';
                    const transportData = document.getElementById('transport_data')?.value || '';
                    const entryPortData = document.getElementById('entry_port_data')?.value || '';
                    const exitPortData = document.getElementById('exit_port_data')?.value || '';

                    // Debug: Log what's being sent to backend
                    console.log('=== DATA BEING SENT TO BACKEND ===');
                    console.log('Hotel data length:', hotelData.length);
                    console.log('Attraction data length:', attractionData.length);
                    console.log('Restaurant data length:', restaurantData.length);
                    console.log('Guide data length:', guideData.length);
                    console.log('Transport data length:', transportData.length);
                    console.log('Entry port data length:', entryPortData.length);
                    console.log('Exit port data length:', exitPortData.length);
                    
                    if (transportData) {
                        try {
                            const parsedTransport = JSON.parse(transportData);
                            console.log('Transport data being sent:', parsedTransport);
                            console.log('Number of transports found:', parsedTransport.length);
                        } catch (e) {
                            console.error('Error parsing transport data:', e);
                        }
                    }

                    // Check if at least one service has data
                    if (!hotelData && !attractionData && !restaurantData && !guideData && 
                        !transportData && !entryPortData && !exitPortData) {
                        alert('Please add at least one service (hotel, attraction, guide, restaurant, or transport)');
                        return false;
                    }

                    // Calculate total price for all services
                    const totalPrice = calculateTotalPackagePrice();

                    try {
                        // Prepare form data
                        const formData = new FormData();
                        formData.append('_token', document.querySelector('input[name="_token"]').value);
                        formData.append('tour_id', tourId);
                        formData.append('agent_id', agentId);
                        formData.append('hotel_data', hotelData || '');
                        formData.append('attraction_data', attractionData || '');
                        formData.append('restaurant_data', restaurantData || '');
                        formData.append('guide_data', guideData || '');
                        formData.append('transport_data', transportData || '');
                        formData.append('entry_port_data', entryPortData || '');
                        formData.append('exit_port_data', exitPortData || '');
                        formData.append('total_price', totalPrice);

                        // Send request to store orders
                        const storeOrdersUrl = '{{ route('single-tour-package.store-orders') }}';
                        console.log('Store orders URL:', storeOrdersUrl);
                 
                        const response = await fetch(storeOrdersUrl, {
                            method: 'POST',
                            headers: {
                                'X-Requested-With': 'XMLHttpRequest',
                                'Accept': 'application/json',
                            },
                            body: formData
                        });

                        if (!response.ok) {
                            console.error('HTTP Error:', response.status, response.statusText);
                            const errorText = await response.text();
                            console.error('Error Response:', errorText);
                            throw new Error(`HTTP ${response.status}: ${response.statusText}`);
                        }

                        const result = await response.json();
                        
                        // Debug: Log the response details
                        console.log('=== BACKEND RESPONSE ===');
                        console.log('Response status:', response.status);
                        console.log('Response data:', result);
                        
                        if (result.success) {
                            console.log('✅ Service orders saved successfully!');
                            if (result.created_orders) {
                                console.log('Created orders:', result.created_orders);
                                result.created_orders.forEach(order => {
                                    if (order.type.includes('travel')) {
                                        console.log(`🚗 Transport order created: ${order.type} - ${order.transport_name || order.service_name} (ID: ${order.order_id})`);
                                    }
                                });
                            }
                            
                            // Store data in session and redirect to thank you page
                            if (result.redirect_url) {
                                // Use a form to pass data via session
                                const form = document.createElement('form');
                                form.method = 'POST';
                                form.action = result.redirect_url;
                                
                                // Add CSRF token
                                const csrfInput = document.createElement('input');
                                csrfInput.type = 'hidden';
                                csrfInput.name = '_token';
                                csrfInput.value = document.querySelector('input[name="_token"]').value;
                                form.appendChild(csrfInput);
                                
                                // Add tour details
                                const tourDetailsInput = document.createElement('input');
                                tourDetailsInput.type = 'hidden';
                                tourDetailsInput.name = 'tour_details';
                                tourDetailsInput.value = JSON.stringify(result.tour_details);
                                form.appendChild(tourDetailsInput);
                                
                                // Add created orders
                                const ordersInput = document.createElement('input');
                                ordersInput.type = 'hidden';
                                ordersInput.name = 'created_orders';
                                ordersInput.value = JSON.stringify(result.created_orders);
                                form.appendChild(ordersInput);
                                
                                document.body.appendChild(form);
                                form.submit();
                            } else {
                                // Fallback to staying on same page
                                showNotification('All service orders saved successfully!', 'success');
                            }
                        } else {
                            alert('Error saving orders: ' + result.message);
                        }
                    } catch (error) {
                        console.error('Error saving orders:', error);
                        alert('Error saving orders: ' + error.message);
                    }
                }
</script>
                </form>
