         // Generate night selection based on date range
    function generateNightSelection() {
         const nightSelectionDiv = document.getElementById('nightSelection');
         nightSelectionDiv.innerHTML = '';
         
         if (tourNights > 0) {
             for (let i = 1; i <= tourNights; i++) {
                 const startDate = moment(tourStartDate).add(i-1, 'days');
                 const endDate = moment(tourStartDate).add(i, 'days');
                 
                const nightButton = document.createElement('button');
                nightButton.type = 'button';
                nightButton.className = 'btn night-btn';
                nightButton.dataset.night = i;
                nightButton.innerHTML = `
                    <div class="d-flex flex-column align-items-center" style="line-height: 1.2;">
                        <strong style="font-size: 0.75rem;">Night ${i}</strong>
                        <small style="font-size: 0.7rem;">${startDate.format('MMM DD')} - ${endDate.format('MMM DD')}</small>
                    </div>
                `;
                 
                 nightButton.addEventListener('click', function() {
                     handleNightSelection(parseInt(this.dataset.night));
                 });
                 
                 nightSelectionDiv.appendChild(nightButton);
             }
         }
    }

     // Handle night selection - treat each night individually (no auto-filling)
    function handleNightSelection(selectedNight) {
         const allNightButtons = document.querySelectorAll('.night-btn');
         let manuallySelectedNights = [];
         
         // Get currently manually selected nights
         allNightButtons.forEach(btn => {
             if (btn.classList.contains('manually-selected')) {
                 manuallySelectedNights.push(parseInt(btn.dataset.night));
             }
         });
         
         // Toggle the clicked night
         if (manuallySelectedNights.includes(selectedNight)) {
             // If clicking on manually selected night, remove it
             manuallySelectedNights = manuallySelectedNights.filter(night => night !== selectedNight);
         } else {
             // Add the new night to manually selected
             manuallySelectedNights.push(selectedNight);
         }
         
        // Update selection - use only manually selected nights (no auto-filling)
        updateConsecutiveSelectionWithColors(manuallySelectedNights, manuallySelectedNights);
        updateNightDisplay();
        
        // Update room price display based on selected nights (weekday/weekend calculation)
        // Use setTimeout to ensure DOM is updated before price calculation
        console.log('Night selection changed, updating room price...');
        setTimeout(() => {
            console.log('Executing delayed price update after night selection...');
            updateRoomPriceDisplay(true); // Force update when nights change
        }, 100);
   }

     // Fill gaps to make consecutive nights
    function fillConsecutiveNights(nights) {
         if (nights.length === 0) return nights;
         
         nights.sort((a, b) => a - b);
         const min = Math.min(...nights);
         const max = Math.max(...nights);
         
         const consecutiveNights = [];
         for (let i = min; i <= max; i++) {
             consecutiveNights.push(i);
         }
         
         return consecutiveNights;
    }

     // Update visual selection of nights with color coding
    function updateConsecutiveSelectionWithColors(manuallySelected, allConsecutive) {
         const allNightButtons = document.querySelectorAll('.night-btn');
         
         allNightButtons.forEach(btn => {
             const nightNumber = parseInt(btn.dataset.night);
             
             // Reset all classes
             btn.classList.remove('active', 'manually-selected', 'auto-selected', 'btn-success', 'btn-warning');
             btn.classList.add('btn-outline-primary');
             
             // Only show manually selected nights (no auto-filling)
                 if (manuallySelected.includes(nightNumber)) {
                 btn.classList.add('active', 'manually-selected', 'btn-success');
                 btn.classList.remove('btn-outline-primary');
             }
         });
    }

     // Legacy function for backward compatibility
    function updateConsecutiveSelection(selectedNights) {
         updateConsecutiveSelectionWithColors(selectedNights, selectedNights);
    }

     // Update night display summary
    function updateNightDisplay() {
         const selectedNights = [];
         const manualNights = [];
         const autoNights = [];
         
         document.querySelectorAll('.night-btn.active').forEach(btn => {
             const nightNum = parseInt(btn.dataset.night);
             selectedNights.push(nightNum);
             
             if (btn.classList.contains('manually-selected')) {
                 manualNights.push(nightNum);
             } else if (btn.classList.contains('auto-selected')) {
                 autoNights.push(nightNum);
             }
         });
         
         selectedNights.sort((a, b) => a - b);
         manualNights.sort((a, b) => a - b);
         autoNights.sort((a, b) => a - b);
         
         if (selectedNights.length > 0) {
            // Format dates for each selected night
            const nightDates = selectedNights.map(night => {
                const nightDate = moment(tourStartDate).add(night-1, 'days');
                return nightDate.format('MMM DD');
            });
            
            // Check if nights are consecutive
            const isConsecutive = selectedNights.length > 1 && 
                selectedNights.every((night, index) => 
                    index === 0 || night === selectedNights[index - 1] + 1
                );
            
             const startNight = Math.min(...selectedNights);
             const endNight = Math.max(...selectedNights);
             const startDate = moment(tourStartDate).add(startNight-1, 'days');
             const endDate = moment(tourStartDate).add(endNight, 'days');
             
            let summaryHTML = `
                <div class="alert" style="background: #d1f2eb; border: 1px solid #7dd3c0; border-radius: 6px; padding: 0.75rem 1rem; margin: 0;">
                    <i class="ri-calendar-check-line me-2" style="color: #667eea;"></i>
                    <strong style="color: #212529; font-size: 0.9rem;">Hotel booked for ${selectedNights.length} night${selectedNights.length > 1 ? 's' : ''}</strong><br>
            `;
            
            // Show date range if consecutive, otherwise show individual nights
            if (isConsecutive && selectedNights.length > 1) {
                summaryHTML += `<small style="color: #495057; font-size: 0.8rem;">${startDate.format('MMM DD')} - ${endDate.format('MMM DD, YYYY')}</small><br>`;
            } else {
                summaryHTML += `<small style="color: #495057; font-size: 0.8rem;">Selected nights: ${selectedNights.join(', ')} (${nightDates.join(', ')})</small><br>`;
            }
            
            summaryHTML += `<small style="color: #6c757d; font-size: 0.75rem;">Selected nights apply to all rooms in this hotel</small>`;
            
           // Show selected nights list
            if (selectedNights.length > 0) {
                summaryHTML += `
                    <hr class="my-2" style="border-color: #b3d9ff;">
                        <div>
                        <small style="color: #495057; font-size: 0.8rem;">
                            <strong>Nights:</strong> ${selectedNights.join(', ')}
                        </small>
                    </div>
                `;
            }
            
            summaryHTML += '</div>';
            document.getElementById('nightSelectionSummary').innerHTML = summaryHTML;
        } else {
            document.getElementById('nightSelectionSummary').innerHTML = `
                <div class="alert" style="background: #e7f3ff; border: 1px solid #b3d9ff; border-radius: 6px; padding: 0.625rem 0.875rem; margin: 0;">
                    <i class="ri-information-line me-2" style="color: #667eea;"></i>
                    <small style="color: #495057; font-size: 0.8rem;">No nights selected. Click on the nights above to select hotel stay.</small>
                </div>
            `;
        }
    }


    // Store hotel data globally for reference (already declared globally)
    
    // Load hotels for city
    window.loadHotelsForCity = function(cityName) {
        const hotelSelect = document.getElementById('hotelSelect');
        const hotelLoadingStatus = document.getElementById('hotelLoadingStatus');
        const roomTypeSelect = document.getElementById('roomTypeSelect');
        const bedTypeSelect = document.getElementById('bedTypeSelect');
        const mealPlanSelect = document.getElementById('mealPlanSelect');
        
        // Show loading state
        // Disable Select2 during loading
        $('#hotelSelect').prop('disabled', true);
        hotelSelect.innerHTML = '<option value="">Loading hotels in ' + cityName + '...</option>';
        hotelSelect.disabled = true;
        
        // Update Select2 with loading state
        if (typeof window.reinitializeSelect2 === 'function') {
            window.reinitializeSelect2('hotelSelect', 'Loading hotels in ' + cityName + '...');
        }
        
        hotelLoadingStatus.innerHTML = '<i class="ri-loader-2-line spin me-1"></i>Loading comprehensive hotel data...';
        hotelLoadingStatus.style.color = '#0d6efd';
        
        // Clear dependent dropdowns
        roomTypeSelect.innerHTML = '<option value="">Select hotel first</option>';
        bedTypeSelect.innerHTML = '<option value="">Select hotel first</option>';
        mealPlanSelect.innerHTML = '<option value="">Select hotel first</option>';
        
        // Clear bed price display
        const bedPriceDisplay = document.getElementById('bedPriceDisplay');
        if (bedPriceDisplay) {
            bedPriceDisplay.style.display = 'none';
        }
        
        // Get current user's DMC ID from authentication
        const currentDmcId = '{{ $finalDmcId }}';
        console.log('Current DMC ID:', currentDmcId);
        
        // Show DMC info in loading status
        hotelLoadingStatus.innerHTML = `<i class="ri-loader-2-line spin me-1"></i>Loading hotels for DMC ${currentDmcId} in ${cityName}...`;
        
        // Fetch hotels from API using DMC-specific endpoint
        fetch(`{{ route('fetch-hotels-by-dmc') }}?city=${encodeURIComponent(cityName)}&dmc_id=${currentDmcId}`)
            .then(response => {
                if (!response.ok) {
                    throw new Error('Network response was not ok');
                }
                return response.json();
            })
            .then(response => {
                console.log('Hotel API Response:', response);
                
                hotelSelect.innerHTML = '<option value="">Select a hotel in ' + cityName + '</option>';
                hotelSelect.disabled = false;
                
                // Handle response format
                if (response.success && response.hotels && response.hotels.length > 0) {
                    // Store hotel data globally
                    hotelData = response.hotels;
                    
                    response.hotels.forEach(hotel => {
                        const starInfo = hotel.hotel_star_rating ? ` (${hotel.hotel_star_rating}⭐)` : '';
                        hotelSelect.innerHTML += `<option value="${hotel.hotel_unique_id}">${hotel.name}${starInfo}</option>`;
                    });
                    
                    hotelLoadingStatus.innerHTML = `<i class="ri-check-line me-1 text-success"></i>${response.hotels.length} hotels found in ${cityName}`;
                    hotelLoadingStatus.style.color = '#198754';
                    console.log(`Loaded ${response.hotels.length} hotels for ${cityName}`);
                    
                    // Enable and reinitialize Select2 after updating options
                    $('#hotelSelect').prop('disabled', false);
                    if (typeof window.reinitializeSelect2 === 'function') {
                        window.reinitializeSelect2('hotelSelect', 'Select a hotel in ' + cityName);
                    }
                    
                    // Add change event listener to hotel select
                    hotelSelect.onchange = function() {
                        clearRoomSelectionForm();
                        updateHotelDependentDropdowns(this.value);
                    };
                    
                    // Load vehicles for transfer if transfer is enabled
                    const transferRequired = document.getElementById('hotel_transfer_required');
                    if (transferRequired && transferRequired.value === 'Yes') {
                        loadHotelTransferVehicles(cityName);
                    }
                } 
                else {
                    hotelData = [];
                    hotelSelect.innerHTML = '<option value="">No hotels found in ' + cityName + '</option>';
                    hotelLoadingStatus.innerHTML = `<i class="ri-information-line me-1 text-warning"></i>No hotels found in ${cityName}`;
                    hotelLoadingStatus.style.color = '#fd7e14';
                    console.log(`No hotels found for ${cityName}`);
                    
                    // Keep enabled even when no hotels, and reinitialize Select2
                    $('#hotelSelect').prop('disabled', false);
                    if (typeof window.reinitializeSelect2 === 'function') {
                        window.reinitializeSelect2('hotelSelect', 'No hotels found in ' + cityName);
                    }
                }
            })
            .catch(error => {
                console.error('Error loading hotels:', error);
                hotelData = [];
                hotelSelect.innerHTML = '<option value="">Error loading hotels</option>';
                hotelSelect.disabled = true;
                $('#hotelSelect').prop('disabled', true); // Disable Select2 on error
                hotelLoadingStatus.innerHTML = '<i class="ri-error-warning-line me-1 text-danger"></i>Error loading hotels';
                hotelLoadingStatus.style.color = '#dc3545';
                
                // Reinitialize Select2 even on error
                if (typeof window.reinitializeSelect2 === 'function') {
                    window.reinitializeSelect2('hotelSelect', 'Error loading hotels');
                }
            });
    };
    
    // Function to toggle hotel transfer fields visibility
    window.toggleHotelTransferFields = function() {
        const transferRequired = document.getElementById('hotel_transfer_required');
        const transferTypeField = document.getElementById('hotel_transfer_type_field');
        const transferWayField = document.getElementById('hotel_transfer_way_field');
        const transferVehicleField = document.getElementById('hotel_transfer_vehicle_field');
        const transferCostField = document.getElementById('hotel_transfer_cost_field');
        const transferPickupField = document.getElementById('hotel_transfer_pickup_field');
        const transferDestinationField = document.getElementById('hotel_transfer_destination_field');
        
        if (transferRequired) {
            if (transferRequired.value === 'Yes') {
                // Show all transfer fields
                if (transferTypeField) transferTypeField.style.display = 'block';
                if (transferWayField) transferWayField.style.display = 'block';
                if (transferVehicleField) transferVehicleField.style.display = 'block';
                if (transferCostField) transferCostField.style.display = 'block';
                if (transferPickupField) transferPickupField.style.display = 'block';
                if (transferDestinationField) transferDestinationField.style.display = 'block';
                
                // Load vehicles and locations if city is already selected
                const citySelect = document.getElementById('hotelCitySelect');
                if (citySelect && citySelect.value) {
                    loadHotelTransferVehicles(citySelect.value);
                    loadHotelTransferLocations(citySelect.value);
                }
            } else {
                // Hide all transfer fields
                if (transferTypeField) transferTypeField.style.display = 'none';
                if (transferWayField) transferWayField.style.display = 'none';
                if (transferVehicleField) transferVehicleField.style.display = 'none';
                if (transferCostField) transferCostField.style.display = 'none';
                if (transferPickupField) transferPickupField.style.display = 'none';
                if (transferDestinationField) transferDestinationField.style.display = 'none';
                
                // Reset transfer fields
                const typeSelect = document.getElementById('hotel_transfer_type');
                const waySelect = document.getElementById('hotel_transfer_way');
                const vehicleSelect = document.getElementById('hotel_transfer_vehicle');
                const costInput = document.getElementById('hotel_transfer_cost');
                const pickupSelect = document.getElementById('hotel_transfer_pickup_location');
                const destinationSelect = document.getElementById('hotel_transfer_destination');
                
                if (typeSelect) typeSelect.value = '';
                if (waySelect) waySelect.value = '';
                if (vehicleSelect) vehicleSelect.innerHTML = '<option value="">Select Vehicle</option>';
                if (costInput) costInput.value = '';
                if (pickupSelect) pickupSelect.innerHTML = '<option value="">Select Pickup Location</option>';
                if (destinationSelect) destinationSelect.innerHTML = '<option value="">Select Destination</option>';
            }
        }
    }
    
    // Function to load vehicles for hotel transfer
    window.loadHotelTransferVehicles = function(cityName) {
        const vehicleSelect = document.getElementById('hotel_transfer_vehicle');
        
        if (!vehicleSelect || !cityName) {
            return;
        }
        
        vehicleSelect.innerHTML = '<option value="">Loading vehicles...</option>';
        vehicleSelect.disabled = true;
        
        fetch(`{{ route('fetch-vehicles-by-city-dmc') }}?city=${encodeURIComponent(cityName)}`)
            .then(response => response.json())
            .then(data => {
                vehicleSelect.innerHTML = '<option value="">Select Vehicle</option>';
                
                if (data.success && data.vehicles && data.vehicles.length > 0) {
                    data.vehicles.forEach(vehicle => {
                        const vehicleInfo = `${vehicle.vehicle_name} (${vehicle.vehicle_type}) - ${vehicle.seating_capacity} seats`;
                        const option = document.createElement('option');
                        option.value = vehicle.vehicle_id;
                        option.textContent = vehicleInfo;
                        option.setAttribute('data-vehicle-name', vehicle.vehicle_name || '');
                        option.setAttribute('data-vehicle-type', vehicle.vehicle_type || '');
                        option.setAttribute('data-seating-capacity', vehicle.seating_capacity || '');
                        option.setAttribute('data-private-price', vehicle.private_price || '');
                        option.setAttribute('data-shared-price', vehicle.shared_price || '');
                        vehicleSelect.appendChild(option);
                    });
                    console.log(`Loaded ${data.vehicles.length} vehicles for hotel transfer in ${cityName}`);
                } else {
                    vehicleSelect.innerHTML += '<option disabled>No vehicles available</option>';
                }
                
                vehicleSelect.disabled = false;
            })
            .catch(error => {
                console.error('Error loading vehicles for hotel transfer:', error);
                vehicleSelect.innerHTML = '<option disabled>Error loading vehicles</option>';
                vehicleSelect.disabled = false;
            });
    }
    
    // Function to load pickup and destination locations for hotel transfer
    window.loadHotelTransferLocations = function(cityName) {
        const pickupSelect = document.getElementById('hotel_transfer_pickup_location');
        const destinationSelect = document.getElementById('hotel_transfer_destination');
        
        if ((!pickupSelect && !destinationSelect) || !cityName) {
            return;
        }
        
        // Show loading state
        if (pickupSelect) {
            pickupSelect.innerHTML = '<option value="">Loading locations...</option>';
            pickupSelect.disabled = true;
        }
        if (destinationSelect) {
            destinationSelect.innerHTML = '<option value="">Loading locations...</option>';
            destinationSelect.disabled = true;
        }
        
        // Get DMC ID for the requests
        const dmcId = '{{ $finalDmcId }}';
        
        // Make AJAX calls for attractions, hotels and restaurants (same as entry_dropoff_location_select)
        Promise.all([
            fetch(`{{ route('fetch-hotels-by-dmc') }}?city=${encodeURIComponent(cityName)}&dmc_id=${dmcId}`)
                .then(response => response.json()),
            fetch(`{{ route('fetch-attractions-by-dmc') }}?city=${encodeURIComponent(cityName)}&dmc_id=${dmcId}`)
                .then(response => response.json()),
            fetch(`{{ route('fetch-restaurants-by-dmc') }}?city=${encodeURIComponent(cityName)}&dmc_id=${dmcId}`)
                .then(response => response.json())
        ])
        .then(([hotelsData, attractionsData, restaurantsData]) => {
            // Function to populate a select element
            const populateSelect = (select) => {
                if (!select) return;
                
                // Clear the dropdown
                select.innerHTML = '<option value="">Select Location</option>';
                
                // Add Hotels
                if (hotelsData.success && hotelsData.hotels && hotelsData.hotels.length > 0) {
                    const hotelGroup = document.createElement('optgroup');
                    hotelGroup.label = 'Hotels';
                    
                    hotelsData.hotels.forEach(hotel => {
                        const option = document.createElement('option');
                        option.value = hotel.hotel_unique_id;
                        option.textContent = hotel.name;
                        option.setAttribute('data-type', 'Hotel');
                        option.setAttribute('data-hotel', JSON.stringify(hotel));
                        hotelGroup.appendChild(option);
                    });
                    
                    select.appendChild(hotelGroup);
                }
                
                // Add Attractions
                if (attractionsData.success && attractionsData.attractions && attractionsData.attractions.length > 0) {
                    const attractionGroup = document.createElement('optgroup');
                    attractionGroup.label = 'Attractions';
                    
                    attractionsData.attractions.forEach(attraction => {
                        const option = document.createElement('option');
                        option.value = attraction.attraction_id;
                        option.textContent = attraction.name;
                        option.setAttribute('data-type', 'Attraction');
                        option.setAttribute('data-attraction', JSON.stringify(attraction));
                        attractionGroup.appendChild(option);
                    });
                    
                    select.appendChild(attractionGroup);
                }
                
                // Add Restaurants
                if (restaurantsData.success && restaurantsData.restaurants && restaurantsData.restaurants.length > 0) {
                    const restaurantGroup = document.createElement('optgroup');
                    restaurantGroup.label = 'Restaurants';
                    
                    restaurantsData.restaurants.forEach(restaurant => {
                        const option = document.createElement('option');
                        option.value = restaurant.restaurant_id;
                        option.textContent = restaurant.name;
                        option.setAttribute('data-type', 'Restaurant');
                        option.setAttribute('data-restaurant', JSON.stringify(restaurant));
                        restaurantGroup.appendChild(option);
                    });
                    
                    select.appendChild(restaurantGroup);
                }
                
                select.disabled = false;
            };
            
            // Populate both selects
            populateSelect(pickupSelect);
            populateSelect(destinationSelect);
            
            console.log(`Loaded pickup and destination locations for hotel transfer in ${cityName}`);
        })
        .catch(error => {
            console.error('Error loading locations for hotel transfer:', error);
            if (pickupSelect) {
                pickupSelect.innerHTML = '<option disabled>Error loading locations</option>';
                pickupSelect.disabled = false;
            }
            if (destinationSelect) {
                destinationSelect.innerHTML = '<option disabled>Error loading locations</option>';
                destinationSelect.disabled = false;
            }
        });
    }
    
    // Update hotel dependent dropdowns by fetching rooms
    window.updateHotelDependentDropdowns = function(hotelId) {
        const roomTypeSelect = document.getElementById('roomTypeSelect');
        const bedTypeSelect = document.getElementById('bedTypeSelect');
        const mealPlanSelect = document.getElementById('mealPlanSelect');
        
        if (!hotelId) {
            // Clear dropdowns if no hotel selected
            if (roomTypeSelect) roomTypeSelect.innerHTML = '<option value="">Select hotel first</option>';
            if (bedTypeSelect) bedTypeSelect.innerHTML = '<option value="">Select hotel first</option>';
            if (mealPlanSelect) mealPlanSelect.innerHTML = '<option value="">Select hotel first</option>';
            return;
        }
        
        // Find selected hotel
        const selectedHotel = hotelData.find(h => h.hotel_unique_id == hotelId);
        if (!selectedHotel) {
            console.error('Selected hotel not found in hotel data');
            return;
        }
        
        console.log('Selected hotel data:', selectedHotel);
        
        // Get current user's DMC ID for room filtering
        const currentDmcId = '{{ $finalDmcId }}';
        
        // Show loading state with DMC info
        if (roomTypeSelect) roomTypeSelect.innerHTML = '<option value="">Loading rooms for DMC...</option>';
        if (bedTypeSelect) bedTypeSelect.innerHTML = '<option value="">Loading rooms for DMC...</option>';
        if (mealPlanSelect) mealPlanSelect.innerHTML = '<option value="">Loading rooms for DMC...</option>';
        
        // Fetch rooms for the selected hotel with DMC filtering
        fetch(`{{ route('fetch-rooms-by-hotel') }}?hotel_id=${encodeURIComponent(hotelId)}&dmc_id=${currentDmcId}`)
            .then(response => {
                if (!response.ok) {
                    throw new Error('Network response was not ok');
                }
                return response.json();
            })
            .then(response => {
                console.log('Rooms API Response:', response);
                
                // Clear dropdowns
                if (roomTypeSelect) roomTypeSelect.innerHTML = '<option value="">Select room type</option>';
                if (bedTypeSelect) bedTypeSelect.innerHTML = '<option value="">Select bed type</option>';
                if (mealPlanSelect) mealPlanSelect.innerHTML = '<option value="">Select meal plan</option>';
        
        // Clear bed price display
        const bedPriceDisplay = document.getElementById('bedPriceDisplay');
        if (bedPriceDisplay) {
            bedPriceDisplay.style.display = 'none';
        }
                
                if (response.success && response.rooms && response.rooms.length > 0) {
                    console.log('Room data structure:', response.rooms[0]); // Debug: log first room structure
                    console.log('Total rooms received:', response.rooms.length);
                    console.log('Current DMC ID for filtering:', currentDmcId);
                    
                    // Filter rooms by DMC ID using only created_by field
                    let dmcFilteredRooms = response.rooms.filter(room => {
                        // Only check created_by field for DMC filtering
                        const roomDmcId = room.created_by;
                        
                        if (roomDmcId) {
                            const isMatch = roomDmcId == currentDmcId;
                            console.log(`Room ${room.room_id}: created_by = ${roomDmcId}, Expected DMC = ${currentDmcId}, Match = ${isMatch}`);
                            return isMatch;
                        } else {
                            // If no created_by info, restrict access for security
                            console.warn(`Room ${room.room_id} has no created_by information - RESTRICTING ACCESS for security`);
                            return false; // Don't show rooms without created_by info
                        }
                    });
                    
                    console.log('Rooms after DMC filtering:', dmcFilteredRooms.length);
                    console.log('DMC filtered rooms:', dmcFilteredRooms);
                    
                    // Use filtered rooms - if no rooms match DMC, show none
                    const roomsToUse = dmcFilteredRooms;
                    
                    // Check if no rooms were found for this DMC
                    if (roomsToUse.length === 0) {
                        console.warn(`No rooms found for DMC ${currentDmcId} in hotel ${hotelId}`);
                        showNotification(`No rooms available for your DMC (ID: ${currentDmcId}) in this hotel. Please contact your administrator.`, 'warning');
                        
                        // Clear dropdowns and show no rooms message
                        if (roomTypeSelect) roomTypeSelect.innerHTML = '<option value="">No rooms available for your DMC</option>';
                        if (bedTypeSelect) bedTypeSelect.innerHTML = '<option value="">No rooms available for your DMC</option>';
                        if (mealPlanSelect) mealPlanSelect.innerHTML = '<option value="">No rooms available for your DMC</option>';
                        
                        // Update DMC filtering status
                        const dmcFilteringStatus = document.getElementById('dmcFilteringStatus');
                        const filteringResults = document.getElementById('filteringResults');
                        if (dmcFilteringStatus && filteringResults) {
                            dmcFilteringStatus.style.display = 'block';
                            filteringResults.textContent = 'No rooms available';
                        }
                        
                        return; // Exit early
                    }
                    
                    // Extract unique values from filtered rooms
                    const roomTypes = [...new Set(roomsToUse.map(room => room.room_type).filter(Boolean))];
                    console.log('Available room types after DMC filtering:', roomTypes);
                    
                    // Create meal plan options based on room types and meal availability
                    const mealPlans = new Set();
                    
                    // Get current guest count
                    const adults = parseInt(document.getElementById('adults').value) || 0;
                    const children = parseInt(document.getElementById('children').value) || 0;
                    const infants = parseInt(document.getElementById('infants').value) || 0;
                    const totalGuests = adults + children; // Infants usually don't count for meals
                    
                    // Group rooms by room type (star rating)
                    const roomsByType = {};
                    roomsToUse.forEach(room => {
                        if (!roomsByType[room.room_type]) {
                            roomsByType[room.room_type] = [];
                        }
                        roomsByType[room.room_type].push(room);
                    });
                    
                    // Filter rooms based on guest count if needed (example: 3 guests = show only 1* rooms)
                    let availableRoomTypes = Object.keys(roomsByType);
                    if (totalGuests >= 3) {
                        // For 3+ guests, filter to show only rooms that can accommodate them
                        availableRoomTypes = availableRoomTypes.filter(roomType => {
                            const rooms = roomsByType[roomType];
                            return rooms.some(room => {
                                // Check if room can accommodate the guests (you may need to adjust this logic)
                                const maxCapacity = room.max_occupancy || room.adult_count || 4; // fallback to 4
                                return maxCapacity >= totalGuests;
                            });
                        });
                        
                        // If guest count is exactly 3 and 1* rooms exist, prioritize them
                        if (totalGuests === 3 && availableRoomTypes.some(type => type.includes('1'))) {
                            availableRoomTypes = availableRoomTypes.filter(type => type.includes('1'));
                        }
                    }
                    
                    // Check what meals are available across all room types (using database boolean fields)
                    const hasBreakfast = roomsToUse.some(room => room.breakfast == 1 || room.breakfast === true);
                    const hasLunch = roomsToUse.some(room => room.lunch == 1 || room.lunch === true);
                    const hasDinner = roomsToUse.some(room => room.dinner == 1 || room.dinner === true);
                    
                    // Generate meal plan options - only show "1 room" options based on database values
                    const roomText = "room";
                    
                    // Add "Room Only" option first
                    mealPlans.add(`${roomText} only`);
                    
                    // Add specific meal options based on database values (breakfast/lunch/dinner = 1)
                    if (hasBreakfast) {
                        mealPlans.add(`${roomText} with breakfast`);
                    }
                    if (hasLunch) {
                        mealPlans.add(`${roomText} with lunch`);
                    }
                    if (hasDinner) {
                        mealPlans.add(`${roomText} with dinner`);
                    }
                    
                    // Add combination meal options based on database values
                    if (hasBreakfast && hasLunch) {
                        mealPlans.add(`${roomText} with breakfast + lunch`);
                    }
                    if (hasBreakfast && hasDinner) {
                        mealPlans.add(`${roomText} with breakfast + dinner`);
                    }
                    if (hasLunch && hasDinner) {
                        mealPlans.add(`${roomText} with lunch + dinner`);
                    }
                    if (hasBreakfast && hasLunch && hasDinner) {
                        mealPlans.add(`${roomText} with all meals (breakfast + lunch + dinner)`);
                    }
                    
                    // Populate room types with pricing information
                    roomTypes.forEach(roomType => {
                        if (roomTypeSelect) {
                            // Find a room of this type to get pricing information
                            const sampleRoom = roomsToUse.find(room => room.room_type === roomType);
                            
                            if (sampleRoom) {
                                // Get the appropriate price based on guest count
                                const adults = parseInt(document.getElementById('adults').value) || 0;
                                const children = parseInt(document.getElementById('children').value) || 0;
                                const totalGuests = adults + children;
                                
                                // Determine if single or double occupancy
                                const isSingleOccupancy = totalGuests <= 1;
                                
                                // For now, default to weekday pricing (you can add weekend logic later)
                                const isWeekend = false;
                                
                                let price = 0;
                                let priceText = '';
                                
                                if (isSingleOccupancy) {
                                    if (isWeekend) {
                                        price = parseFloat(sampleRoom.weekend_price) || 0;
                                        priceText = ` - Weekend: $${price}`;
                                    } else {
                                        price = parseFloat(sampleRoom.weekday_price) || 0;
                                        priceText = ` - Weekday: $${price}`;
                                    }
                                } else {
                                    if (isWeekend) {
                                        price = parseFloat(sampleRoom.double_weekend_price) || 0;
                                        priceText = ` - Double Weekend: $${price}`;
                                    } else {
                                        price = parseFloat(sampleRoom.double_weekday_price) || 0;
                                        priceText = ` - Double Weekday: $${price}`;
                                    }
                                }
                                
                                // Create option with price information
                                const option = document.createElement('option');
                                option.value = roomType;
                                option.textContent = `${roomType}${priceText}`;
                                
                                option.dataset.roomType = roomType;
                                option.dataset.weekdayPrice = sampleRoom.weekday_price || 0;
                                option.dataset.weekendPrice = sampleRoom.weekend_price || 0;
                                option.dataset.doubleWeekdayPrice = sampleRoom.double_weekday_price || 0;
                                option.dataset.doubleWeekendPrice = sampleRoom.double_weekend_price || 0;
                                option.dataset.roomId = sampleRoom.room_id;
                                
                                // Store meal prices in dataset
                                option.dataset.breakfastPrice = sampleRoom.breakfast_price || 0;
                                option.dataset.lunchPrice = sampleRoom.lunch_price || 0;
                                option.dataset.dinnerPrice = sampleRoom.dinner_price || 0;
                                option.dataset.breakfast = sampleRoom.breakfast || 0;
                                option.dataset.lunch = sampleRoom.lunch || 0;
                                option.dataset.dinner = sampleRoom.dinner || 0;
                                roomTypeSelect.appendChild(option);
                                
                                console.log(`Added room type option: ${roomType} with price $${price} (${isSingleOccupancy ? 'Single' : 'Double'} ${isWeekend ? 'Weekend' : 'Weekday'})`);
                                console.log(`Meal prices: Breakfast: $${sampleRoom.breakfast_price || 0}, Lunch: $${sampleRoom.lunch_price || 0}, Dinner: $${sampleRoom.dinner_price || 0}`);
                                console.log(`Sample room data for ${roomType}:`, sampleRoom);
                                console.log(`Dataset stored for ${roomType}:`, {
                                    breakfastPrice: option.dataset.breakfastPrice,
                                    lunchPrice: option.dataset.lunchPrice,
                                    dinnerPrice: option.dataset.dinnerPrice
                                });
                            } else {
                                // Fallback if no sample room found
                            roomTypeSelect.innerHTML += `<option value="${roomType}">${roomType}</option>`;
                            }
                        }
                    });
                    
                    // Add event listener for room type selection
                    if (roomTypeSelect) {
                        roomTypeSelect.onchange = function() {
                            clearRoomTypeDependentFields();
                            updateBedTypesForRoom(this.value);
                            updateRoomPriceDisplay(true); // Force update when room type changes
                        };
                    }
                    
                    // Add event listener for number of rooms
                    const numberOfRoomsInput = document.getElementById('numberOfRooms');
                    if (numberOfRoomsInput) {
                        numberOfRoomsInput.addEventListener('input', function() {
                            updateRoomPriceDisplay(true); // Force update when number of rooms changes
                        });
                        numberOfRoomsInput.addEventListener('change', function() {
                            updateRoomPriceDisplay(true); // Force update when number of rooms changes
                        });
                    }
                    
                    // Add event listeners for guest count changes (affects single vs double occupancy pricing)
                    const adultsInput = document.getElementById('adults');
                    const childrenInput = document.getElementById('children');
                    if (adultsInput) {
                        adultsInput.addEventListener('change', function() {
                            updateRoomPriceDisplay(true); // Force update when adults count changes
                        });
                    }
                    if (childrenInput) {
                        childrenInput.addEventListener('change', function() {
                            updateRoomPriceDisplay(true); // Force update when children count changes
                        });
                    }
                    
                    // Track manual edits to price field
                    const roomPriceDisplay = document.getElementById('roomPriceDisplay');
                    if (roomPriceDisplay) {
                        roomPriceDisplay.addEventListener('input', function() {
                            // Mark as manually edited when user types
                            this.dataset.manuallyEdited = 'true';
                        });
                        roomPriceDisplay.addEventListener('focus', function() {
                            // Mark as manually edited when user focuses (they might paste or edit)
                            // Only if current value is not empty and not $0.00
                            const currentValue = this.value.replace('$', '').trim();
                            if (currentValue && currentValue !== '0.00') {
                                this.dataset.manuallyEdited = 'true';
                            }
                        });
                    }
                    
                    // Store room data globally for bed fetching (use filtered rooms)
                    window.roomData = roomsToUse;
                    
                    // Debug: Log the room data structure
                    console.log('=== ROOM DATA STORED ===');
                    console.log('Total rooms stored:', roomsToUse.length);
                    if (roomsToUse.length > 0) {
                        console.log('First room sample:', roomsToUse[0]);
                        console.log('Meal prices in first room:', {
                            breakfast_price: roomsToUse[0].breakfast_price,
                            lunch_price: roomsToUse[0].lunch_price,
                            dinner_price: roomsToUse[0].dinner_price
                        });
                    }
                    
                    // For bed types, we'll populate them when a room type is selected
                    if (bedTypeSelect) {
                        bedTypeSelect.innerHTML = '<option value="">Select room type first</option>';
                    }
                    
                    // Populate meal plans (cleaned up)
                    const cleanedMealPlans = cleanMealPlanOptions([...mealPlans]);
                    cleanedMealPlans.forEach(mealPlan => {
                        if (mealPlanSelect) {
                            mealPlanSelect.innerHTML += `<option value="${mealPlan}">${mealPlan}</option>`;
                        }
                    });
                    
                    // Add event listener for meal plan selection
                    if (mealPlanSelect) {
                        mealPlanSelect.onchange = function() {
                            updateRoomCostCalculation();
                        };
                    }
                    
                    // Reinitialize Select2 for all three dropdowns after updating options
                    if (typeof window.reinitializeSelect2 === 'function') {
                        window.reinitializeSelect2('roomTypeSelect', 'Select room type');
                        window.reinitializeSelect2('bedTypeSelect', 'Select room type first');
                        window.reinitializeSelect2('mealPlanSelect', 'Select meal plan');
                    }
                    
                    console.log(`Loaded ${roomsToUse.length} rooms for hotel ${hotelId} (filtered by DMC ${currentDmcId})`);
                    
                    // Show notification about DMC filtering
                    if (dmcFilteredRooms.length !== response.rooms.length) {
                        const filteredCount = dmcFilteredRooms.length;
                        const totalCount = response.rooms.length;
                        showNotification(`DMC Filtering (created_by): Showing ${filteredCount} rooms out of ${totalCount} total rooms for DMC ${currentDmcId}`, 'info');
                        
                        // Update DMC filtering status display
                        const dmcFilteringStatus = document.getElementById('dmcFilteringStatus');
                        const filteringResults = document.getElementById('filteringResults');
                        if (dmcFilteringStatus && filteringResults) {
                            dmcFilteringStatus.style.display = 'block';
                            filteringResults.textContent = `${filteredCount}/${totalCount} rooms shown`;
                        }
                    } else {
                        // Hide DMC filtering status if no filtering occurred
                        const dmcFilteringStatus = document.getElementById('dmcFilteringStatus');
                        if (dmcFilteringStatus) {
                            dmcFilteringStatus.style.display = 'none';
                        }
                    }
                } else {
                    console.log('No rooms found for hotel:', hotelId);
                    if (roomTypeSelect) roomTypeSelect.innerHTML = '<option value="">No rooms available</option>';
                    if (bedTypeSelect) bedTypeSelect.innerHTML = '<option value="">No rooms available</option>';
                    if (mealPlanSelect) mealPlanSelect.innerHTML = '<option value="">No rooms available</option>';
                }
            })
            .catch(error => {
                console.error('Error loading rooms:', error);
                if (roomTypeSelect) roomTypeSelect.innerHTML = '<option value="">Error loading rooms</option>';
                if (bedTypeSelect) bedTypeSelect.innerHTML = '<option value="">Error loading rooms</option>';
                if (mealPlanSelect) mealPlanSelect.innerHTML = '<option value="">Error loading rooms</option>';
            });
        
        // Display hotel information
        displayHotelInfo(selectedHotel);
    };
    
    // Display hotel information
    window.displayHotelInfo = function(hotel) {
        const hotelLoadingStatus = document.getElementById('hotelLoadingStatus');
        
        if (hotelLoadingStatus && hotel) {
            // Build HTML from hotel object
            let infoHTML = '';
            
            if (hotel.name) {
                infoHTML += `<div class="hotel-info mt-2">`;
                infoHTML += `<strong><i class="ri-hotel-line me-1"></i>${hotel.name}</strong>`;
                
                if (hotel.hotel_star_rating) {
                    infoHTML += ` <span class="badge bg-warning">${hotel.hotel_star_rating}⭐</span>`;
                }
                
                if (hotel.address) {
                    infoHTML += `<div class="small text-muted mt-1"><i class="ri-map-pin-line me-1"></i>${hotel.address}</div>`;
                }
                
                if (hotel.phone) {
                    infoHTML += `<div class="small text-muted"><i class="ri-phone-line me-1"></i>${hotel.phone}</div>`;
                }
                
                infoHTML += `</div>`;
            }
            
            // Only update if we have content to display
            if (infoHTML) {
                hotelLoadingStatus.innerHTML = infoHTML;
            }
        }
    };
    
    // Update bed types for selected room type
    window.updateBedTypesForRoom = function(roomType) {
        const bedTypeSelect = document.getElementById('bedTypeSelect');
        const roomTypeSelect = document.getElementById('roomTypeSelect');
        
        if (!roomType || !window.roomData) {
            if (bedTypeSelect) bedTypeSelect.innerHTML = '<option value="">Select room type first</option>';
            return;
        }
        
        // Get the selected room type option to access pricing data
        const selectedRoomOption = roomTypeSelect.options[roomTypeSelect.selectedIndex];
        if (!selectedRoomOption) {
            console.error('No room type option selected');
            return;
        }
        
        console.log('Selected room type option:', selectedRoomOption);
        console.log('Room type dataset:', selectedRoomOption.dataset);
        
        // Find rooms of the selected type
        const selectedRooms = window.roomData.filter(room => room.room_type === roomType);
        
        if (selectedRooms.length === 0) {
            if (bedTypeSelect) bedTypeSelect.innerHTML = '<option value="">No rooms of this type</option>';
            return;
        }
        
        console.log('Selected rooms for bed types:', selectedRooms);
        
        // Clear dropdown and show loading
        if (bedTypeSelect) bedTypeSelect.innerHTML = '<option value="">Loading bed types...</option>';
        
        // Get the first room ID to fetch beds (since all rooms of same type should have similar bed options)
        const firstRoom = selectedRooms[0];
        const roomId = firstRoom.room_id;
        
        console.log('Fetching beds for room ID:', roomId);
        
        // Fetch beds from the beds table using the existing API endpoint
        fetch(`{{ route('fetch-beds-by-room') }}?room_id=${roomId}`)
            .then(response => {
                if (!response.ok) {
                    throw new Error('Network response was not ok');
                }
                return response.json();
            })
            .then(data => {
                console.log('Beds API Response:', data);
                
                if (bedTypeSelect) bedTypeSelect.innerHTML = '<option value="">Select bed type</option>';
                
                if (data.success && data.beds && data.beds.length > 0) {
                    // Populate bed types from the beds table
                    data.beds.forEach(bed => {
                        if (bedTypeSelect) {
                            // Create descriptive bed type text based on beds table structure
                            let bedTypeText = bed.room_type || 'Standard Bed';
                            
                            // Add occupancy info if available
                            if (bed.max_occupancy) {
                                bedTypeText += ` - Max ${bed.max_occupancy} guests`;
                            }
                            
                            // Add adult/child info if available
                            if (bed.adult_count && bed.child_count) {
                                bedTypeText += ` (${bed.adult_count}A+${bed.child_count}C)`;
                            }
                            
                            // Add extra bed info if available
                            if (bed.extra_bed) {
                                bedTypeText += ` + Extra Bed`;
                                if (bed.extra_bed_price) {
                                    bedTypeText += ` ($${bed.extra_bed_price})`;
                                }
                            }
                            
                            // Add baby cot info if available
                            if (bed.baby_cot) {
                                bedTypeText += ` + Baby Cot`;
                                if (bed.baby_cot_price) {
                                    bedTypeText += ` ($${bed.baby_cot_price})`;
                                }
                            }
                            console.log('Bed type in beds table===:', bed.room_type);
                            // Store bed data in option for later use
                            const option = document.createElement('option');
                            option.value = bed.bed_id;
                            option.textContent = bedTypeText;
                            option.dataset.bedId = bed.bed_id;
                            option.dataset.roomId = bed.room_id;
                            option.dataset.bedType = bed.room_type || '';
                            option.dataset.maxOccupancy = bed.max_occupancy || '';
                            option.dataset.noOfRooms = bed.no_of_rooms || '';
                            option.dataset.extraBedPrice = bed.extra_bed_price || '';
                            option.dataset.babyCotPrice = bed.baby_cot_price || '';
                            option.dataset.extraBedAvailable = bed.extra_bed ? 'true' : 'false';
                            
                            bedTypeSelect.appendChild(option);
                        }
                    });
                    
                    console.log(`Loaded ${data.beds.length} bed types for room type ${roomType} from beds table`);
                    
                    // Show bed price display
                    const bedPriceDisplay = document.getElementById('bedPriceDisplay');
                    if (bedPriceDisplay) {
                        bedPriceDisplay.style.display = 'block';
                    }
                    
                    // Reinitialize Select2 for bed type dropdown
                    if (typeof window.reinitializeSelect2 === 'function') {
                        window.reinitializeSelect2('bedTypeSelect', 'Select bed type');
                    }
                    
                } else {
                    // No beds found in beds table, show fallback options
                    console.log('No beds found in beds table, showing fallback options');
                    
                    if (bedTypeSelect) bedTypeSelect.innerHTML = '<option value="">No bed types available</option>';
                    
                    // Hide bed price display
                    const bedPriceDisplay = document.getElementById('bedPriceDisplay');
                    if (bedPriceDisplay) {
                        bedPriceDisplay.style.display = 'none';
                    }
                    
                    // Reinitialize Select2 even when no beds available
                    if (typeof window.reinitializeSelect2 === 'function') {
                        window.reinitializeSelect2('bedTypeSelect', 'No bed types available');
                    }
                }
                
                // Add event listener for bed type selection
                if (bedTypeSelect) {
                    bedTypeSelect.onchange = function() {
                        updatePricingForBed(this.value);
                    };
                }
            })
            .catch(error => {
                console.error('Error fetching beds:', error);
                if (bedTypeSelect) bedTypeSelect.innerHTML = '<option value="">Error loading bed types</option>';
                
                // Hide bed price display
                const bedPriceDisplay = document.getElementById('bedPriceDisplay');
                if (bedPriceDisplay) {
                    bedPriceDisplay.style.display = 'none';
                }
                
                // Reinitialize Select2 even on error
                if (typeof window.reinitializeSelect2 === 'function') {
                    window.reinitializeSelect2('bedTypeSelect', 'Error loading bed types');
                }
            });
    };

    // Update pricing when bed type is selected
    window.updatePricingForBed = function(bedTypeValue) {
        console.log('updatePricingForBed called with:', bedTypeValue);
        const bedTypeSelect = document.getElementById('bedTypeSelect');
        const selectedOption = bedTypeSelect.options[bedTypeSelect.selectedIndex];
        const priceDisplay = document.getElementById('bedPriceDisplay');
        
        console.log('Selected option:', selectedOption);
        console.log('Selected option dataset:', selectedOption ? selectedOption.dataset : 'No option');
        
        if (selectedOption && selectedOption.dataset.bedId) {
            console.log('Selected bed option:', selectedOption);
            console.log('Bed dataset:', selectedOption.dataset);
            
            // Get bed information from dataset
            const bedId = selectedOption.dataset.bedId;
            const roomId = selectedOption.dataset.roomId;
            const bedType = selectedOption.dataset.bedType;
            const maxOccupancy = selectedOption.dataset.maxOccupancy;
            const noOfRooms = selectedOption.dataset.noOfRooms;
            const extraBedPrice = parseFloat(selectedOption.dataset.extraBedPrice) || 0;
            const babyCotPrice = parseFloat(selectedOption.dataset.babyCotPrice) || 0;
            const extraBedAvailable = selectedOption.dataset.extraBedAvailable === 'true';
            
            // Create detailed price display
            let priceText = '';
            let totalPrice = 0;
            
            if (extraBedPrice > 0) {
                priceText += `Extra Bed: $${extraBedPrice.toFixed(2)}`;
                totalPrice += extraBedPrice;
            }
            
            if (babyCotPrice > 0) {
                if (priceText) priceText += ' | ';
                priceText += `Baby Cot: $${babyCotPrice.toFixed(2)}`;
                totalPrice += babyCotPrice;
            }
            
            if (totalPrice === 0) {
                priceText = 'No additional charges';
            }
            
            console.log(`Selected bed type: ${selectedOption.textContent}`);
            console.log(`Max Occupancy: ${maxOccupancy}`);
            
            // Update price display
            if (priceDisplay) {
                priceDisplay.style.display = 'block';
                priceDisplay.innerHTML = `
                    <div class="small">
                        <div><strong>Max Occupancy:</strong> ${maxOccupancy || 'N/A'}</div>
                    </div>
                `;
            }
            
            // Update person selector based on max occupancy and extra bed availability
            updatePersonSelector(parseInt(maxOccupancy) || 1, extraBedAvailable);
            
            // Store the selected bed information for later use
            window.selectedBedInfo = {
                bedId: bedId,
                roomId: roomId,
                maxOccupancy: maxOccupancy,
                noOfRooms: noOfRooms,
                extraBedPrice: extraBedPrice,
                babyCotPrice: babyCotPrice,
                extraBedAvailable: extraBedAvailable,
                totalPrice: totalPrice,
                bedType: bedType
            };
            
            console.log('Stored selectedBedInfo:', window.selectedBedInfo);
        } else {
            // Hide price display if no bed selected
            if (priceDisplay) {
                priceDisplay.style.display = 'none';
            }
            window.selectedBedInfo = null;
            
            // Reset person selector
            const personSelector = document.getElementById('personSelector');
            if (personSelector) {
                personSelector.innerHTML = '<div class="text-muted small">Select bed type first</div>';
            }
            
            // Hide guest count information
            const guestCountInfo = document.getElementById('guestCountInfo');
            if (guestCountInfo) {
                guestCountInfo.style.display = 'none';
            }
            
            // Reset cost summary
            const costSummary = document.getElementById('roomCostSummary');
            if (costSummary) {
                costSummary.innerHTML = '<div class="text-muted small">Select room details first</div>';
            }
            
            // Reset selected persons input
            const selectedPersonsInput = document.getElementById('selectedPersons');
            if (selectedPersonsInput) {
                selectedPersonsInput.value = '1';
            }
        }
    }

    // Function to update room price display based on room type and number of rooms
    function updateRoomPriceDisplay(forceUpdate = false) {
        const roomPriceDisplay = document.getElementById('roomPriceDisplay');
        const roomTypeSelect = document.getElementById('roomTypeSelect');
        const numberOfRoomsInput = document.getElementById('numberOfRooms');
        
        if (!roomPriceDisplay) {
            return;
        }
        
        // Check if price was manually edited (unless forceUpdate is true)
        const isManuallyEdited = roomPriceDisplay.dataset.manuallyEdited === 'true';
        if (isManuallyEdited && !forceUpdate) {
            // Don't overwrite manually entered price
            return;
        }
        
        // If no room type selected, show 0.00 (SGD is fixed prefix)
        if (!roomTypeSelect || !roomTypeSelect.value) {
            roomPriceDisplay.value = '0.00';
            roomPriceDisplay.dataset.manuallyEdited = 'false';
            return;
        }
        
        const selectedOption = roomTypeSelect.options[roomTypeSelect.selectedIndex];
        if (!selectedOption || !selectedOption.dataset) {
            roomPriceDisplay.value = '0.00';
            return;
        }
        
        // Get guest count to determine single vs double occupancy
        const adults = parseInt(document.getElementById('adults').value) || 0;
        const children = parseInt(document.getElementById('children').value) || 0;
        const totalGuests = adults + children;
        const isSingleOccupancy = totalGuests <= 1;
        
        // Get base price per room (use weekday price as default, or calculate based on selected nights)
        let pricePerRoom = 0;
        
        // Check if nights are selected
        const selectedNights = document.querySelectorAll('.night-btn.active');
        
        console.log('=== CHECKING NIGHT SELECTION FOR PRICE CALCULATION ===');
        console.log('Selected nights query result:', selectedNights);
        console.log('Selected nights length:', selectedNights.length);
        console.log('Selected nights array:', Array.from(selectedNights).map(n => n.dataset.night));
        console.log('window.tourStartDate:', window.tourStartDate);
        console.log('tourStartDate (alternative):', window.tourStartDate || tourStartDate);
        
        // Also check for manually-selected and auto-selected classes as backup
        if (selectedNights.length === 0) {
            const manuallySelected = document.querySelectorAll('.night-btn.manually-selected');
            const autoSelected = document.querySelectorAll('.night-btn.auto-selected');
            console.log('Fallback check - manually selected:', manuallySelected.length);
            console.log('Fallback check - auto selected:', autoSelected.length);
        }
        
        console.log('Condition result:', selectedNights.length > 0 && window.tourStartDate);
        
        // Use tourStartDate from global scope if window.tourStartDate is not available
        const startDate = window.tourStartDate || (typeof tourStartDate !== 'undefined' ? tourStartDate : null);
        
        if (selectedNights.length > 0 && startDate) {
            // Calculate price based on selected nights (weekday/weekend)
            let totalPrice = 0;
            let weekdayCount = 0;
            let weekendCount = 0;
            
            const weekdayPrice = isSingleOccupancy 
                ? parseFloat(selectedOption.dataset.weekdayPrice) || 0
                : parseFloat(selectedOption.dataset.doubleWeekdayPrice) || 0;
            const weekendPrice = isSingleOccupancy 
                ? parseFloat(selectedOption.dataset.weekendPrice) || 0
                : parseFloat(selectedOption.dataset.doubleWeekendPrice) || 0;
            
            selectedNights.forEach(nightBtn => {
                const nightNum = parseInt(nightBtn.dataset.night);
                const nightDate = moment(startDate).add(nightNum - 1, 'days');
                const dayOfWeek = nightDate.day(); // 0 = Sunday, 6 = Saturday
                const isWeekend = dayOfWeek === 0 || dayOfWeek === 6;
                const nightPrice = isWeekend ? weekendPrice : weekdayPrice;
                totalPrice += nightPrice;
                
                console.log(`Night ${nightNum} (${nightDate.format('MMM DD, ddd')}): ${isWeekend ? 'WEEKEND' : 'WEEKDAY'} - Price: ${nightPrice}`);
                
                if (isWeekend) {
                    weekendCount++;
                } else {
                    weekdayCount++;
                }
            });
            
            pricePerRoom = totalPrice;
            
            console.log('Room price calculation on night selection:', {
                totalNights: selectedNights.length,
                weekdayNights: weekdayCount,
                weekendNights: weekendCount,
                weekdayPrice: weekdayPrice,
                weekendPrice: weekendPrice,
                pricePerRoom: pricePerRoom,
                isSingleOccupancy: isSingleOccupancy
            });
        } else {
            // No nights selected, use weekday price as default
            pricePerRoom = isSingleOccupancy 
                ? parseFloat(selectedOption.dataset.weekdayPrice) || 0
                : parseFloat(selectedOption.dataset.doubleWeekdayPrice) || 0;
            console.log('No nights selected, using weekday price as default:', pricePerRoom);
        }
        
        // Get number of rooms
        const numberOfRooms = parseInt(numberOfRoomsInput?.value) || 1;
        
        // Calculate total price
        const totalPrice = pricePerRoom * numberOfRooms;
        
        console.log('Final room price calculation:', {
            pricePerRoom: pricePerRoom,
            numberOfRooms: numberOfRooms,
            totalPrice: totalPrice,
            formattedPrice: totalPrice.toFixed(2)
        });
        
        // Update display (SGD is fixed prefix, only set numeric value)
        roomPriceDisplay.value = totalPrice.toFixed(2);
        roomPriceDisplay.dataset.manuallyEdited = 'false'; // Mark as auto-calculated
        
        console.log('Room price display updated to:', roomPriceDisplay.value);
    }

    // Update room cost calculation
    function updateRoomCostCalculation() {
        const costSummary = document.getElementById('roomCostSummary');
        const selectedPersonsInput = document.getElementById('selectedPersons');
        const mealPlanSelect = document.getElementById('mealPlanSelect');
        
        if (!costSummary || !window.selectedBedInfo) {
            if (costSummary) {
                costSummary.innerHTML = '<div class="text-muted small">Select room details first</div>';
            }
            return;
        }
        
        const numPersons = parseInt(selectedPersonsInput?.value) || 1;
        const selectedMealPlan = mealPlanSelect?.value || '';
        
        // Get base room price from selected room type
        let baseRoomPrice = 0;
        let mealPrices = {
            breakfast_price: 0,
            lunch_price: 0,
            dinner_price: 0
        };
        
        const roomTypeSelect = document.getElementById('roomTypeSelect');
        if (roomTypeSelect && roomTypeSelect.value) {
            const selectedOption = roomTypeSelect.options[roomTypeSelect.selectedIndex];
            if (selectedOption && selectedOption.dataset) {
                // Get guest count to determine single vs double occupancy
                const adults = parseInt(document.getElementById('adults').value) || 0;
                const children = parseInt(document.getElementById('children').value) || 0;
                const totalGuests = adults + children;
                
                // Determine if single or double occupancy
                const isSingleOccupancy = totalGuests <= 1;
                
                // Determine if it's weekend (simplified - you might want to use actual dates)
                const isWeekend = false; // You can implement weekend detection here if needed
                
                // Get base room price
                if (isSingleOccupancy) {
                    if (isWeekend) {
                        baseRoomPrice = parseFloat(selectedOption.dataset.weekendPrice) || 0;
                    } else {
                        baseRoomPrice = parseFloat(selectedOption.dataset.weekdayPrice) || 0;
                    }
                } else {
                    if (isWeekend) {
                        baseRoomPrice = parseFloat(selectedOption.dataset.doubleWeekendPrice) || 0;
                    } else {
                        baseRoomPrice = parseFloat(selectedOption.dataset.doubleWeekdayPrice) || 0;
                    }
                }
                
                // Get meal prices
                mealPrices = {
                    breakfast_price: parseFloat(selectedOption.dataset.breakfastPrice) || 0,
                    lunch_price: parseFloat(selectedOption.dataset.lunchPrice) || 0,
                    dinner_price: parseFloat(selectedOption.dataset.dinnerPrice) || 0
                };
                
                console.log('=== ROOM AND MEAL PRICE RETRIEVAL ===');
                console.log('Selected room type:', roomTypeSelect.value);
                console.log('Base room price:', baseRoomPrice);
                console.log('Retrieved meal prices:', mealPrices);
            }
            
            // Fallback: If dataset values are 0, try to get from global room data
            if (mealPrices.breakfast_price === 0 && mealPrices.lunch_price === 0 && mealPrices.dinner_price === 0) {
                console.log('Dataset values are 0, trying fallback from global room data...');
                if (window.roomData && Array.isArray(window.roomData)) {
                    const selectedRoomType = roomTypeSelect.value;
                    const matchingRoom = window.roomData.find(room => room.room_type === selectedRoomType);
                    if (matchingRoom) {
                        mealPrices = {
                            breakfast_price: parseFloat(matchingRoom.breakfast_price) || 0,
                            lunch_price: parseFloat(matchingRoom.lunch_price) || 0,
                            dinner_price: parseFloat(matchingRoom.dinner_price) || 0
                        };
                        console.log('Fallback meal prices from room data:', mealPrices);
                    } else {
                        console.log('No matching room found in global room data for:', selectedRoomType);
                    }
                } else {
                    console.log('Global room data not available:', window.roomData);
                }
            }
        }
        
        // Calculate meal cost (per selected guest)
        const mealCostPerPerson = calculateMealCostPerPerson(selectedMealPlan, mealPrices);
        const totalMealCost = mealCostPerPerson * numPersons;
        
        // Calculate extra bed cost
        let extraBedCost = 0;
        const bedInfo = window.selectedBedInfo;
        if (bedInfo && bedInfo.extraBedAvailable && bedInfo.extraBedPrice > 0) {
            const maxOccupancy = parseInt(bedInfo.maxOccupancy) || 0;
            // If selected persons exceed max occupancy, calculate extra bed cost
            if (numPersons > maxOccupancy) {
                const extraPersons = numPersons - maxOccupancy;
                extraBedCost = extraPersons * parseFloat(bedInfo.extraBedPrice);
                console.log(`Extra bed calculation: ${extraPersons} extra persons × $${bedInfo.extraBedPrice} = $${extraBedCost}`);
            }
        }
        
        console.log('Meal cost calculation:', {
            selectedMealPlan: selectedMealPlan,
            mealCostPerPerson: mealCostPerPerson,
            numPersons: numPersons,
            totalMealCost: totalMealCost
        });
        
        console.log('Extra bed calculation:', {
            bedInfo: bedInfo,
            maxOccupancy: bedInfo ? bedInfo.maxOccupancy : 'N/A',
            numPersons: numPersons,
            extraBedCost: extraBedCost
        });
        
        // Calculate total: Base room price + meal costs + extra bed costs
        const totalCost = baseRoomPrice + totalMealCost + extraBedCost;
        
        // Update display
        costSummary.innerHTML = `
            <div class="cost-item">
                <span>Base Room Price:</span>
                <span>$${baseRoomPrice.toFixed(2)}</span>
            </div>
            <div class="cost-item">
                <span>Meal Plan (${numPersons} guest${numPersons > 1 ? 's' : ''}):</span>
                <span>$${totalMealCost.toFixed(2)}</span>
            </div>
            ${extraBedCost > 0 ? `
                <div class="cost-item">
                    <span>Extra Bed Cost:</span>
                    <span>$${extraBedCost.toFixed(2)}</span>
                </div>
            ` : ''}
            <hr class="my-1">
            <div class="cost-item fw-bold">
                <span>Total per Room:</span>
                <span>$${totalCost.toFixed(2)}</span>
            </div>
        `;
        
        console.log(`Room cost calculation: Base Room: $${baseRoomPrice}, Meal (${numPersons} guests): $${totalMealCost}, Total per Room: $${totalCost}`);
    }

    // Calculate meal cost per person
    function calculateMealCostPerPerson(mealPlan, mealPrices = null) {
        if (!mealPlan || mealPlan.toLowerCase().includes('only') || mealPlan === 'Not specified') {
            return 0;
        }
        
        // Use database meal prices if available, otherwise return 0 (no fallback defaults)
        if (!mealPrices || typeof mealPrices !== 'object') {
            return 0;
        }
        
        let totalCost = 0;
        const planLower = mealPlan.toLowerCase();
        console.log(mealPrices)
        // Parse dynamic meal plan to determine which meals are included
        if (planLower.includes('breakfast') || planLower.includes('bf')) {
            const breakfastPrice = parseFloat(mealPrices.breakfast_price) || 0;
            totalCost += breakfastPrice;
        }
        if (planLower.includes('lunch')) {
            const lunchPrice = parseFloat(mealPrices.lunch_price) || 0;
            totalCost += lunchPrice;
        }
        if (planLower.includes('dinner')) {
            const dinnerPrice = parseFloat(mealPrices.dinner_price) || 0;
            totalCost += dinnerPrice;
        }
        
        return totalCost;
    }

    // Calculate meal cost for selected number of persons (legacy function for compatibility)
    function calculateMealCostForPersons(mealPlan, numPersons, mealPrices = null) {
        const costPerPerson = calculateMealCostPerPerson(mealPlan, mealPrices);
        return costPerPerson * numPersons;
    }

    // Clean meal plan options to remove duplicates while preserving dynamic format
    function cleanMealPlanOptions(mealPlans) {
        const cleanedPlans = new Set();
        
        mealPlans.forEach(plan => {
            if (!plan || plan.trim() === '') return;
            
            let cleanedPlan = plan.trim();
            
            // Keep the original dynamic format - don't convert to static values
            // Just ensure consistent formatting
            cleanedPlan = cleanedPlan.replace(/\s+/g, ' '); // Normalize whitespace
            
            // Only add if it's a meaningful meal plan
            if (cleanedPlan) {
                cleanedPlans.add(cleanedPlan);
            }
        });
        
        // Convert to array and sort
        const sortedPlans = Array.from(cleanedPlans).sort((a, b) => {
            // Put "room only" options first, then others alphabetically
            if (a.toLowerCase().includes('only')) return -1;
            if (b.toLowerCase().includes('only')) return 1;
            return a.localeCompare(b);
        });
        
        console.log('Dynamic meal plans:', sortedPlans);
        return sortedPlans;
    }

    // Update person selector based on max occupancy
    function updatePersonSelector(maxOccupancy, extraBedAvailable = false) {
        console.log('updatePersonSelector called with:', maxOccupancy, extraBedAvailable);
        const personSelector = document.getElementById('personSelector');
        const selectedPersonsInput = document.getElementById('selectedPersons');
        const guestCountInfo = document.getElementById('guestCountInfo');
        const currentGuestCount = document.getElementById('currentGuestCount');
        const maxOccupancyDisplay = document.getElementById('maxOccupancyDisplay');
        
        if (!personSelector || maxOccupancy < 1) {
            console.log('Person selector not found or invalid max occupancy:', personSelector, maxOccupancy);
            return;
        }
        
        // Clear existing content
        personSelector.innerHTML = '';
        
        // Get current guest count from the form (tour pax)
        const adults = parseInt(document.getElementById('adults').value) || 0;
        const children = parseInt(document.getElementById('children').value) || 0;
        const totalGuests = adults + children; // This is the tour pax
        
        // Use the passed extraBedAvailable parameter, fallback to selectedBedInfo if not provided
        const isExtraBedAvailable = extraBedAvailable !== undefined ? extraBedAvailable : (window.selectedBedInfo && window.selectedBedInfo.extraBedAvailable);
        
        // Show guest count information
        if (guestCountInfo) {
            guestCountInfo.style.display = 'block';
        }
        if (currentGuestCount) {
            currentGuestCount.textContent = totalGuests;
        }
        if (maxOccupancyDisplay) {
            // Update display to show max occupancy including extra bed
            const maxWithExtraBed = isExtraBedAvailable ? maxOccupancy + 1 : maxOccupancy;
            maxOccupancyDisplay.textContent = `${maxOccupancy}${isExtraBedAvailable ? ' (+1 extra bed)' : ''}`;
        }
        
        // Apply the person selection rules:
        // 1. Calculate max occupancy including extra bed if available
        const maxRoomOccupancy = isExtraBedAvailable ? maxOccupancy + 1 : maxOccupancy;
        
        // 2. Apply the rule: min(tour pax, max occupancy [+ extra bed if available])
        const maxSelectable = Math.min(totalGuests, maxRoomOccupancy);
        
        console.log('Person selection rules applied:', {
            tourPax: totalGuests,
            maxOccupancy: maxOccupancy,
            extraBedAvailable: isExtraBedAvailable,
            maxRoomOccupancy: maxRoomOccupancy,
            maxSelectable: maxSelectable
        });
        
        // Handle case where no persons can be selected (tour pax = 0)
        if (maxSelectable <= 0) {
            personSelector.innerHTML = '<div class="text-muted small">No guests selected for this tour</div>';
            if (selectedPersonsInput) {
                selectedPersonsInput.value = 0;
            }
            return;
        }
        
        // Create person symbols with icons
        for (let i = 1; i <= maxSelectable; i++) {
            const personSymbol = document.createElement('div');
            personSymbol.className = 'person-symbol';
            
            // Use person icons: single person for 1, multiple people for 2+
            // Add extra bed indicator for persons exceeding max occupancy
            if (i > maxOccupancy && isExtraBedAvailable) {
                personSymbol.textContent = '🛏️'; // Extra bed icon
                personSymbol.title = `Extra bed (${i} persons)`;
            } else {
                personSymbol.textContent = i === 1 ? '👤' : '👥';
                personSymbol.title = `${i} person${i > 1 ? 's' : ''}`;
            }
            
            personSymbol.dataset.persons = i;
            personSymbol.setAttribute('data-persons', i);
            
            // Set default selection based on the new rules
            // Default to 1 if tour pax > 0, otherwise no selection
            const defaultSelection = totalGuests > 0 ? Math.min(totalGuests, maxSelectable) : 1;
            if (i === defaultSelection) {
                personSymbol.classList.add('selected');
                if (selectedPersonsInput) {
                    selectedPersonsInput.value = defaultSelection;
                }
            }
            
            // Add click event
            personSymbol.addEventListener('click', function() {
                selectPersons(i);
            });
            
            personSelector.appendChild(personSymbol);
        }
        
        // Update cost calculation
        updateRoomCostCalculation();
    }

    // Select number of persons
    function selectPersons(numPersons) {
        const personSelector = document.getElementById('personSelector');
        const selectedPersonsInput = document.getElementById('selectedPersons');
        
        if (!personSelector) {
            console.error('Person selector element not found');
            return;
        }
        
        // Get bed information for validation
        const bedInfo = window.selectedBedInfo;
        console.log('selectPersons - bedInfo:', bedInfo);
        if (!bedInfo) {
            console.error('No bed information available for validation');
            return;
        }
        
        const maxOccupancy = parseInt(bedInfo.maxOccupancy) || 0;
        const extraBedAvailable = bedInfo.extraBedAvailable || false;
        
        // Validate person count against max occupancy and extra bed rules
        if (numPersons > maxOccupancy) {
            if (extraBedAvailable && numPersons === maxOccupancy + 1) {
                // Allow 1 extra person if extra bed is available
                console.log(`Extra bed allocated for ${numPersons} persons (max occupancy: ${maxOccupancy})`);
            } else if (extraBedAvailable && numPersons > maxOccupancy + 1) {
                // Show error if exceeding max occupancy + extra bed limit
                showNotification('Maximum occupancy reached including extra bed.', 'error');
                return;
            } else if (!extraBedAvailable) {
                // Show error if no extra bed available and exceeding max occupancy
                showNotification(`Maximum occupancy is ${maxOccupancy} persons. No extra bed available.`, 'error');
                return;
            }
        }
        
        // Additional validation: Check if selected persons exceed total guest count (tour pax)
        const adults = parseInt(document.getElementById('adults').value) || 0;
        const children = parseInt(document.getElementById('children').value) || 0;
        const totalGuests = adults + children; // This is the tour pax
        
        // Apply the rule: user cannot select more persons than the tour pax
        if (numPersons > totalGuests) {
            showNotification(`Cannot select more than ${totalGuests} persons (tour pax limit)`, 'error');
            return;
        }
        
        console.log(`Person selection validated: ${numPersons} persons (tour pax: ${totalGuests}, max occupancy: ${maxOccupancy}, extra bed available: ${extraBedAvailable})`);
        
        // Update visual selection
        const symbols = personSelector.querySelectorAll('.person-symbol');
        symbols.forEach(symbol => {
            symbol.classList.remove('selected');
            if (parseInt(symbol.dataset.persons) === numPersons) {
                symbol.classList.add('selected');
            }
        });
        
        // Update hidden input
        if (selectedPersonsInput) {
            selectedPersonsInput.value = numPersons;
        }
        
        // Update cost calculation
        updateRoomCostCalculation();
        
        console.log(`Selected ${numPersons} persons for room occupancy`);
    }

