         // Add Hotel Function
    window.addHotel = function() {
         // Check if travel dates are set
         if (!tourStartDate) {
             alert('Please add travel dates first before adding hotels.');
             return;
         }
         
         // Check if guests (pax) are added
         const adults = parseInt(document.getElementById('adults').value) || 0;
         const children = parseInt(document.getElementById('children').value) || 0;
         const totalGuests = adults + children;
         
         if (totalGuests === 0) {
             alert('Please add guests (PAX) first before adding hotels.');
             return;
         }
         
         const hotelSelect = document.getElementById('hotelSelect');
         const roomType = document.getElementById('roomTypeSelect').value;
         const bedType = document.getElementById('bedTypeSelect').value;
         const mealPlan = document.getElementById('mealPlanSelect').value;
         const selectedPersons = document.getElementById('selectedPersons').value || '1';
         // Get number of rooms from the input field
         const numberOfRoomsInput = document.getElementById('numberOfRooms');
         let numberOfRooms = 1; // default
         if (numberOfRoomsInput) {
             numberOfRooms = parseInt(numberOfRoomsInput.value) || 1;
         }
         console.log(`Number of rooms from user input: ${numberOfRooms} rooms`);
         
         if (!hotelSelect.value) {
             showNotification('Please select a hotel first.', 'warning');
             return;
         }
         
         const selectedNights = document.querySelectorAll('.night-btn.active');
         if (selectedNights.length === 0) {
             showNotification('Please select at least one night for this hotel.', 'warning');
             return;
         }
         
         // Get selected night numbers and dates
         const nightNumbers = Array.from(selectedNights).map(btn => parseInt(btn.dataset.night));
         nightNumbers.sort((a, b) => a - b);
         
         const startNight = Math.min(...nightNumbers);
         const endNight = Math.max(...nightNumbers);
         const checkInDate = moment(tourStartDate).add(startNight-1, 'days');
         const checkOutDate = moment(tourStartDate).add(endNight, 'days');
         
        // Get bed information if available
        const bedInfo = window.selectedBedInfo || {};
        
        // Calculate price per night based on each night's day of the week
        const roomTypeSelect = document.getElementById('roomTypeSelect');
        let totalRoomPrice = 0;
        let priceBreakdown = [];
        let weekdayNights = 0;
        let weekendNights = 0;
        
        if (roomTypeSelect && roomTypeSelect.value === roomType) {
            const selectedOption = roomTypeSelect.options[roomTypeSelect.selectedIndex];
            if (selectedOption && selectedOption.dataset) {
                // Get guest count to determine single vs double occupancy
                const adults = parseInt(document.getElementById('adults').value) || 0;
                const children = parseInt(document.getElementById('children').value) || 0;
                const totalGuests = adults + children;
                
                // Determine if single or double occupancy
                const isSingleOccupancy = totalGuests <= 1;
                
                // Get prices from dataset
                const weekdayPrice = isSingleOccupancy 
                    ? parseFloat(selectedOption.dataset.weekdayPrice) || 0
                    : parseFloat(selectedOption.dataset.doubleWeekdayPrice) || 0;
                const weekendPrice = isSingleOccupancy 
                    ? parseFloat(selectedOption.dataset.weekendPrice) || 0
                    : parseFloat(selectedOption.dataset.doubleWeekendPrice) || 0;
                
                // Calculate price for each selected night
                nightNumbers.forEach(nightNum => {
                    const nightDate = moment(tourStartDate).add(nightNum-1, 'days');
                    const dayOfWeek = nightDate.day(); // 0 = Sunday, 6 = Saturday
                    const isWeekend = dayOfWeek === 0 || dayOfWeek === 6;
                    
                    const nightPrice = isWeekend ? weekendPrice : weekdayPrice;
                    totalRoomPrice += nightPrice;
                    
                    if (isWeekend) {
                        weekendNights++;
                    } else {
                        weekdayNights++;
                    }
                    
                    priceBreakdown.push({
                        night: nightNum,
                        date: nightDate.format('MMM DD'),
                        dayOfWeek: nightDate.format('ddd'),
                        isWeekend: isWeekend,
                        price: nightPrice
                    });
                });
                
                console.log(`=== PRICE BREAKDOWN FOR ${roomType} ===`);
                console.log(`Total nights: ${nightNumbers.length}`);
                console.log(`Weekday nights: ${weekdayNights} @ $${weekdayPrice} each`);
                console.log(`Weekend nights: ${weekendNights} @ $${weekendPrice} each`);
                console.log(`Total room price: $${totalRoomPrice}`);
                console.log('Per-night breakdown:', priceBreakdown);
            }
        }
        
        // Validate that we have a valid price
        if (totalRoomPrice <= 0) {
            showNotification('Warning: Room price is $0.00. Please check room type selection.', 'warning');
            console.warn('Room price is 0 or invalid:', totalRoomPrice);
        }
         
         // Get meal price information from the selected room type
         let mealPrices = {
             breakfast_price: 0,
             lunch_price: 0,
             dinner_price: 0
         };
         
         console.log('=== MEAL PRICE FETCHING DEBUG ===');
         console.log('Room type select element:', roomTypeSelect);
         console.log('Room type value:', roomType);
         console.log('Room type select value:', roomTypeSelect ? roomTypeSelect.value : 'N/A');
         
         if (roomTypeSelect && roomTypeSelect.value === roomType) {
             const selectedOption = roomTypeSelect.options[roomTypeSelect.selectedIndex];
             console.log('Selected option:', selectedOption);
             console.log('Selected option dataset:', selectedOption ? selectedOption.dataset : 'N/A');
             
             if (selectedOption && selectedOption.dataset) {
                                 // Get meal prices directly from the room type option dataset
                // Get meal prices from database (no fallback defaults)
                mealPrices = {
                    breakfast_price: parseFloat(selectedOption.dataset.breakfastPrice) || 0,
                    lunch_price: parseFloat(selectedOption.dataset.lunchPrice) || 0,
                    dinner_price: parseFloat(selectedOption.dataset.dinnerPrice) || 0
                };
                 
                 console.log('Meal prices from room type option:', mealPrices);
                 console.log('Dataset values:', {
                     breakfastPrice: selectedOption.dataset.breakfastPrice,
                     lunchPrice: selectedOption.dataset.lunchPrice,
                     dinnerPrice: selectedOption.dataset.dinnerPrice
                 });
                 
                 // Also log the meal availability flags
