             const bedTypeSelectEl = document.getElementById('bedTypeSelect');
             if (bedTypeSelectEl) {
                 if ($('#bedTypeSelect').hasClass('select2-hidden-accessible')) {
                     $('#bedTypeSelect').select2('destroy');
                 }
                 bedTypeSelectEl.innerHTML = '<option value="">Bed Type</option>';
                 bedTypeSelectEl.value = '';
                 $('#bedTypeSelect').select2({
                     placeholder: "Bed Type",
                     allowClear: true,
                     width: '100%'
                 });
             }
             
             // Reset meal plan select
             const mealPlanSelectEl = document.getElementById('mealPlanSelect');
             if (mealPlanSelectEl) {
                 if ($('#mealPlanSelect').hasClass('select2-hidden-accessible')) {
                     $('#mealPlanSelect').select2('destroy');
                 }
                 mealPlanSelectEl.innerHTML = '<option value="">Select Meal Plans</option>';
                 mealPlanSelectEl.value = '';
                 $('#mealPlanSelect').select2({
                     placeholder: "Select Meal Plans",
                     allowClear: true,
                     width: '100%'
                 });
             }
         } catch (error) {
             console.error('Error resetting Select2 dropdowns:', error);
         }
         
         // Reset number of rooms
         const numberOfRoomsEl = document.getElementById('numberOfRooms');
         if (numberOfRoomsEl) {
             numberOfRoomsEl.value = '1';
         }
         
         // Reset bed price display
         const bedPriceDisplay = document.getElementById('bedPriceDisplay');
         if (bedPriceDisplay) {
             bedPriceDisplay.style.display = 'none';
             const priceSpan = bedPriceDisplay.querySelector('span');
             if (priceSpan) {
                 priceSpan.textContent = '$0.00';
             }
         }
         
         // Reset person selector
         const personSelector = document.getElementById('personSelector');
         if (personSelector) {
             personSelector.innerHTML = '<div class="text-muted small">Select bed type first</div>';
         }
         
         // Reset selected persons
         const selectedPersonsInput = document.getElementById('selectedPersons');
         if (selectedPersonsInput) {
             selectedPersonsInput.value = '1';
         }
         
         // Reset room price display
         const roomPriceDisplay = document.getElementById('roomPriceDisplay');
         if (roomPriceDisplay) {
             roomPriceDisplay.value = '0.00';
             if (roomPriceDisplay.dataset) {
                 roomPriceDisplay.dataset.manuallyEdited = 'false';
             }
         }
         
         // Clear selected bed info
         window.selectedBedInfo = null;
         
         // Reset hotel city loader and message
         const hotelCityLoader = document.getElementById('hotelCityLoader');
         if (hotelCityLoader) {
             hotelCityLoader.style.display = 'none';
         }
         
         const hotelCityMessage = document.getElementById('hotelCityMessage');
         if (hotelCityMessage) {
             hotelCityMessage.style.display = 'none';
         }
         
         // Clear hotel loading status
         const hotelLoadingStatus = document.getElementById('hotelLoadingStatus');
         if (hotelLoadingStatus) {
             hotelLoadingStatus.innerHTML = '';
         }
         
         // Reset transfer options form fields
         const transferRequiredSelect = document.getElementById('hotel_transfer_required');
         if (transferRequiredSelect) {
             transferRequiredSelect.value = 'No';
             // Trigger change to hide transfer fields
             if (typeof toggleHotelTransferFields === 'function') {
                 toggleHotelTransferFields();
             }
         }
         
         // Clear transfer option fields
         const transferTypeSelect = document.getElementById('hotel_transfer_type');
         const transferWaySelect = document.getElementById('hotel_transfer_way');
         const transferVehicleSelect = document.getElementById('hotel_transfer_vehicle');
         const transferCostInput = document.getElementById('hotel_transfer_cost');
         const transferPickupSelect = document.getElementById('hotel_transfer_pickup_location');
         const transferDestinationSelect = document.getElementById('hotel_transfer_destination');
         
         if (transferTypeSelect) transferTypeSelect.value = '';
         if (transferWaySelect) transferWaySelect.value = '';
         if (transferVehicleSelect) {
             $('#hotel_transfer_vehicle').val(null).trigger('change');
         }
         if (transferCostInput) transferCostInput.value = '';
         if (transferPickupSelect) {
             $('#hotel_transfer_pickup_location').val(null).trigger('change');
         }
         if (transferDestinationSelect) {
             $('#hotel_transfer_destination').val(null).trigger('change');
         }
         
         // Clear night selection
         updateConsecutiveSelection([]);
         updateNightDisplay();
         
                 // Show package details and submit sections if hotels are added
        if (selectedHotels.length > 0) {
            document.getElementById('packageDetailsSection').style.display = 'block';
            document.getElementById('submitSection').style.display = 'block';
            
            // Ensure transport section is visible (it should already be visible from createTourPackage)
            if (document.getElementById('transportSection').style.display !== 'block') {
                document.getElementById('transportSection').style.display = 'block';
                generateDailyServices();
                
                // Transport zones will be loaded when cities are selected in each transport section
                
                // Populate ports for the newly created transport sections
                populatePortsDropdowns();
            }
        }

        
    };

         // Display selected hotels
    function displaySelectedHotels() {
         const container = document.getElementById('selectedHotels');
         
         if (selectedHotels.length === 0) {
             container.innerHTML = `
                 <div class="alert d-flex align-items-center" style="background: #e7f3ff; border: 1px solid #b3d9ff; border-radius: 6px; padding: 0.625rem 0.875rem; margin: 0;">
                     <i class="ri-information-line me-2" style="color: #667eea;"></i>
                     <span style="color: #495057; font-size: 0.85rem;">No hotels selected yet. Choose your hotels above.</span>
                 </div>
             `;
         } else {
             let hotelsHtml = '';
             selectedHotels.forEach((hotel, index) => {
                 hotelsHtml += `
                     <div class="card mb-3" style="border: 1px solid #dee2e6; border-radius: 8px; box-shadow: 0 2px 6px rgba(0,0,0,0.05); overflow: hidden;">
                         <div class="card-header" style="background: linear-gradient(135deg, #667eea 0%, #764ba2 100%); border: none; padding: 0.875rem 1.25rem;">
                             <div class="d-flex justify-content-between align-items-center">
                                 <h6 class="mb-0 fw-bold text-white" style="color: #ffffff !important; font-size: 1rem;">
                                     <i class="ri-hotel-line me-2"></i>${hotel.name}
                                 </h6>
                                 <button type="button" class="btn btn-sm" onclick="removeHotel(${index})" style="background: rgba(255, 255, 255, 0.2); border: 1px solid rgba(255, 255, 255, 0.3); color: #ffffff; border-radius: 6px; padding: 0.25rem 0.75rem; font-size: 0.8rem; transition: all 0.2s;">
                                     <i class="ri-delete-bin-line me-1"></i> Remove
                                 </button>
                             </div>
                         </div>
                         <div class="card-body" style="padding: 1.25rem; background: #ffffff;">
                             <div class="row g-3">
                                 <div class="col-md-6">
                                     <div class="mb-2 d-flex flex-wrap gap-1">
                                         <span class="badge" style="background: #667eea; color: #ffffff; border-radius: 4px; font-size: 0.75rem; padding: 0.375rem 0.75rem; font-weight: 500;">${hotel.numberOfRooms} Room(s)</span>
                                         <span class="badge" style="background: #b3d9ff; color: #667eea; border-radius: 4px; font-size: 0.75rem; padding: 0.375rem 0.75rem; font-weight: 500;">${hotel.roomType}</span>
                                         <span class="badge" style="background: #d1f2eb; color: #28a745; border-radius: 4px; font-size: 0.75rem; padding: 0.375rem 0.75rem; font-weight: 500;">${hotel.bedType}</span>
                                     </div>
                                     <small class="d-block" style="color: #6c757d; font-size: 0.85rem;">
                                         <i class="ri-restaurant-line me-1" style="color: #667eea;"></i>Meal Plan: <strong style="color: #495057;">${hotel.mealPlan}</strong>
                                     </small>
                                 </div>
                                 <div class="col-md-6">
                                     <div class="alert mb-0 py-2" style="background: #d1f2eb; border: 1px solid #7dd3c0; border-radius: 6px; padding: 0.75rem 1rem;">
                                         <div class="d-flex justify-content-between align-items-center">
                                             <div>
                                                 <strong style="color: #212529; font-size: 0.9rem;">Hotel booked for ${hotel.totalNights} nights</strong><br>
                                                 <small style="color: #495057; font-size: 0.8rem;">${hotel.checkInDate} - ${hotel.checkOutDate}, 2025</small><br>
                                                 <small style="color: #6c757d; font-size: 0.75rem;">Consecutive hotel nights selected</small>
                                             </div>
                                             <div class="badge" style="background: linear-gradient(135deg, #667eea 0%, #764ba2 100%); color: #ffffff; border-radius: 6px; font-size: 0.85rem; font-weight: 600; padding: 0.5rem 0.875rem; box-shadow: 0 2px 6px rgba(102, 126, 234, 0.3);">${hotel.totalNights} nights</div>
                                         </div>
                                     </div>
                                     
                                     <!-- Meal Costs Breakdown -->
                                     ${hotel.mealPlan && !hotel.mealPlan.includes('only') ? `
                                         <div class="mt-2 p-2 rounded" style="background: #f8f9fa; border: 1px solid #e9ecef; border-radius: 6px;">
                                             <small class="d-block mb-1" style="color: #495057; font-size: 0.8rem; font-weight: 600;">
                                                 <i class="ri-restaurant-line me-1" style="color: #667eea;"></i>Meal Costs Breakdown:
                                             </small>
                                             ${hotel.mealPrices ? `
                                                 <div style="font-size: 0.8rem;">
                                                     ${hotel.mealPlan.includes('breakfast') || hotel.mealPlan.includes('bf') ? `
                                                         <div class="d-flex justify-content-between mb-1">
                                                             <span style="color: #495057;">Breakfast:</span>
                                                             <span style="color: #212529; font-weight: 500;">$${hotel.mealPrices.breakfast_price || 0} × ${hotel.selectedPersons || 1} persons × ${hotel.totalNights} nights × ${hotel.numberOfRooms} rooms = $${(hotel.mealPrices.breakfast_price || 0) * (hotel.selectedPersons || 1) * hotel.totalNights * hotel.numberOfRooms}</span>
                                                         </div>
                                                     ` : ''}
                                                     ${hotel.mealPlan.includes('lunch') ? `
                                                         <div class="d-flex justify-content-between mb-1">
                                                             <span style="color: #495057;">Lunch:</span>
                                                             <span style="color: #212529; font-weight: 500;">$${hotel.mealPrices.lunch_price || 0} × ${hotel.selectedPersons || 1} persons × ${hotel.totalNights} nights × ${hotel.numberOfRooms} rooms = $${(hotel.mealPrices.lunch_price || 0) * (hotel.selectedPersons || 1) * hotel.totalNights * hotel.numberOfRooms}</span>
                                                         </div>
                                                     ` : ''}
                                                     ${hotel.mealPlan.includes('dinner') ? `
                                                         <div class="d-flex justify-content-between mb-1">
                                                             <span style="color: #495057;">Dinner:</span>
                                                             <span style="color: #212529; font-weight: 500;">$${hotel.mealPrices.dinner_price || 0} × ${hotel.selectedPersons || 1} persons × ${hotel.totalNights} nights × ${hotel.numberOfRooms} rooms = $${(hotel.mealPrices.dinner_price || 0) * (hotel.selectedPersons || 1) * hotel.totalNights * hotel.numberOfRooms}</span>
                                                         </div>
                                                     ` : ''}
                                                 </div>
                                             ` : '<small style="color: #6c757d; font-size: 0.8rem;">Meal prices not available</small>'}
                                         </div>
                                     ` : ''}
                                     
                                    <!-- Cost Summary -->
                                    <div class="mt-2 p-2 rounded" style="background: linear-gradient(135deg, #667eea 0%, #764ba2 100%); border: none; border-radius: 6px; color: #ffffff;">
                                        <small class="d-block mb-2" style="font-size: 0.85rem; font-weight: 600; color: #ffffff !important;">
                                            <i class="ri-calculator-line me-1"></i>Cost Summary:
                                        </small>
                                        <div style="font-size: 0.8rem;">
                                            <div class="d-flex justify-content-between mb-1" style="color: rgba(255, 255, 255, 0.9);">
                                                <span>Room Cost:</span>
                                                <span style="font-weight: 500; color: #ffffff !important;">
                                                    ${hotel.weekdayNights || hotel.weekendNights ? (() => {
                                                        // Calculate actual weekday and weekend prices from breakdown
                                                        let weekdayPrice = 0;
                                                        let weekendPrice = 0;
                                                        
                                                        if (hotel.priceBreakdown && hotel.priceBreakdown.length > 0) {
                                                            // Get actual prices from breakdown
                                                            const weekdayNight = hotel.priceBreakdown.find(n => !n.isWeekend);
                                                            const weekendNight = hotel.priceBreakdown.find(n => n.isWeekend);
                                                            weekdayPrice = weekdayNight ? weekdayNight.price : 0;
                                                            weekendPrice = weekendNight ? weekendNight.price : 0;
                                                        }
                                                        
                                                        let breakdown = '';
                                                        if (hotel.weekdayNights && weekdayPrice > 0) {
                                                            breakdown += `${hotel.weekdayNights} weekday @ $${weekdayPrice.toFixed(2)}/night`;
                                                        }
                                                        if (hotel.weekdayNights && hotel.weekendNights && weekdayPrice > 0 && weekendPrice > 0) {
                                                            breakdown += ' + ';
                                                        }
                                                        if (hotel.weekendNights && weekendPrice > 0) {
                                                            breakdown += `${hotel.weekendNights} weekend @ $${weekendPrice.toFixed(2)}/night`;
                                                        }
                                                        if (breakdown) {
                                                            breakdown += ` × ${hotel.numberOfRooms} room(s) = `;
                                                        }
                                                        return breakdown;
                                                    })() : ''}
                                                    $${(hotel.price || 0) * hotel.numberOfRooms}
                                                </span>
                                            </div>
                                            ${hotel.customRoomPrice ? `
                                                <div class="d-flex justify-content-between mb-1" style="color: rgba(255, 255, 255, 0.9);">
                                                    <span>Custom Room Cost:</span>
                                                    <span style="font-weight: 500; color: #ffffff !important;">$${hotel.customRoomPrice}</span>
                                                </div>
                                            ` : ''}
                                            ${hotel.mealPlan && !hotel.mealPlan.includes('only') ? `
                                                <div class="d-flex justify-content-between mb-1" style="color: rgba(255, 255, 255, 0.9);">
                                                    <span>Meal Cost:</span>
                                                    <span style="font-weight: 500; color: #ffffff !important;">$${(() => {
                                                        if (typeof window.calculateCorrectMealCosts === 'function') {
                                                            return window.calculateCorrectMealCosts(hotel.mealPlan, hotel.totalNights, hotel.selectedPersons || 1, 0, hotel.mealPrices, hotel.numberOfRooms);
                                                        }
                                                        // Fallback calculation if function not available
                                                        let mealCost = 0;
                                                        const totalGuests = hotel.selectedPersons || 1;
                                                        if (hotel.mealPrices && typeof hotel.mealPrices === 'object') {
                                                            if (hotel.mealPlan.includes('breakfast') || hotel.mealPlan.includes('bf')) {
                                                                mealCost += (parseFloat(hotel.mealPrices.breakfast_price) || 0) * totalGuests * hotel.totalNights * hotel.numberOfRooms;
                                                            }
                                                            if (hotel.mealPlan.includes('lunch')) {
                                                                mealCost += (parseFloat(hotel.mealPrices.lunch_price) || 0) * totalGuests * hotel.totalNights * hotel.numberOfRooms;
                                                            }
                                                            if (hotel.mealPlan.includes('dinner')) {
                                                                mealCost += (parseFloat(hotel.mealPrices.dinner_price) || 0) * totalGuests * hotel.totalNights * hotel.numberOfRooms;
                                                            }
                                                        }
                                                        return mealCost;
                                                    })()}</span>
                                                </div>
                                            ` : ''}
                                            ${hotel.extraBedPrice && hotel.extraBedPrice > 0 && hotel.selectedPersons > hotel.maxOccupancy ? `
                                                <div class="d-flex justify-content-between mb-1" style="color: rgba(255, 255, 255, 0.9);">
                                                    <span>Extra Bed Cost:</span>
                                                    <span style="font-weight: 500; color: #ffffff !important;">$${hotel.extraBedPrice} × ${hotel.selectedPersons - hotel.maxOccupancy} × ${hotel.numberOfRooms} × ${hotel.totalNights} = $${hotel.extraBedPrice * (hotel.selectedPersons - hotel.maxOccupancy) * hotel.numberOfRooms * hotel.totalNights}</span>
                                                </div>
                                            ` : ''}
                                            <hr class="my-2" style="border-color: rgba(255, 255, 255, 0.3);">
                                            <div class="d-flex justify-content-between" style="font-weight: 700; font-size: 0.9rem; color: #ffffff !important;">
                                                <span>Total:</span>
                                                <span>$${(() => {
                                                    const roomCost = (hotel.price || 0) * hotel.numberOfRooms;
                                                    let mealCost = 0;
                                                    if (typeof window.calculateCorrectMealCosts === 'function') {
                                                        mealCost = window.calculateCorrectMealCosts(hotel.mealPlan, hotel.totalNights, hotel.selectedPersons || 1, 0, hotel.mealPrices, hotel.numberOfRooms);
                                                    } else {
                                                        // Fallback calculation if function not available
                                                        const totalGuests = hotel.selectedPersons || 1;
                                                        if (hotel.mealPrices && typeof hotel.mealPrices === 'object') {
                                                            if (hotel.mealPlan && (hotel.mealPlan.includes('breakfast') || hotel.mealPlan.includes('bf'))) {
                                                                mealCost += (parseFloat(hotel.mealPrices.breakfast_price) || 0) * totalGuests * hotel.totalNights * hotel.numberOfRooms;
                                                            }
                                                            if (hotel.mealPlan && hotel.mealPlan.includes('lunch')) {
                                                                mealCost += (parseFloat(hotel.mealPrices.lunch_price) || 0) * totalGuests * hotel.totalNights * hotel.numberOfRooms;
                                                            }
                                                            if (hotel.mealPlan && hotel.mealPlan.includes('dinner')) {
                                                                mealCost += (parseFloat(hotel.mealPrices.dinner_price) || 0) * totalGuests * hotel.totalNights * hotel.numberOfRooms;
                                                            }
                                                        }
                                                    }
                                                    const extraBedCost = (hotel.extraBedPrice && hotel.extraBedPrice > 0 && hotel.selectedPersons > hotel.maxOccupancy) ? 
                                                        hotel.extraBedPrice * (hotel.selectedPersons - hotel.maxOccupancy) * hotel.numberOfRooms * hotel.totalNights : 0;
                                                    return roomCost + mealCost + extraBedCost;
                                                })()}</span>
                                            </div>
                                        </div>
                                    </div>
                                 </div>
                             </div>
                         </div>
                     </div>
                 `;
             });
             container.innerHTML = hotelsHtml;
         }
         
         // Update summary
         const totalHotelsEl = document.getElementById('totalHotels');
         if (totalHotelsEl) {
             totalHotelsEl.textContent = selectedHotels.length;
         }
         const totalNights = selectedHotels.reduce((sum, hotel) => sum + hotel.totalNights, 0);
         const totalNightsEl = document.getElementById('totalNights');
         if (totalNightsEl) {
             totalNightsEl.textContent = totalNights + ' Nights';
         }
    }

         // Generate daily services based on tour dates
    function generateDailyServices() {
         const container = document.getElementById('dailyServicesContainer');
         
         // Ensure we have valid tour dates
         if (!tourStartDate || !tourEndDate) {
             console.log('Tour dates not set, cannot generate daily services');
             return;
         }
         
         console.log('Generating daily services for tour');
         
         const totalDays = moment(tourEndDate).diff(moment(tourStartDate), 'days') + 1;
         
         // Update day count
         document.getElementById('transportDayCount').textContent = totalDays + ' Days';
         
         let servicesHTML = '';
         
        // Only show Day 1 and last day with exit port (if more than 1 day)
        const daysToShow = totalDays > 1 ? [1, totalDays] : [1];
        
        for (let dayIndex = 0; dayIndex < daysToShow.length; dayIndex++) {
            const day = daysToShow[dayIndex];
            const currentDate = moment(tourStartDate).add(day-1, 'days');
            const isFirstDay = day === 1;
            const isLastDay = day === totalDays;
             
                         servicesHTML += `
                <div class="daily-service-section" id="day${day}">
             `;
            // Entry Port Services (Only on Day 1)
