    // Handle confirm selection
    document.addEventListener('DOMContentLoaded', function() {
        document.getElementById('confirmDishSelection').addEventListener('click', function() {
            if (window.currentDishSelection) {
                const { day, index, mealId, dishType } = window.currentDishSelection;
                
                // Mark the selected dish button as selected
                const dishContainer = document.getElementById(`day${day}_dish_container_${index}`);
                if (dishContainer) {
                    // Remove previous selection
                    dishContainer.querySelectorAll('.dish-option-btn').forEach(btn => {
                        btn.classList.remove('selected');
                    });
                    
                    // Mark current selection
                    dishContainer.querySelectorAll('.dish-option-btn').forEach(btn => {
                        if (btn.dataset.mealId === mealId) {
                            btn.classList.add('selected');
                        }
                    });
                }
                
                // Close modal
                const modal = bootstrap.Modal.getInstance(document.getElementById('dishSelectionModal'));
                modal.hide();
                
                // Reset selection
                window.currentDishSelection = null;
            }
        });
    });
    
    // Load dishes for specific restaurant
    function loadDishesForRestaurant(day, restaurantId, index, mealPeriod = null) {
        const dishSelect = document.getElementById('day' + day + '_dish_' + index);
        if (!dishSelect) {
            console.log('Dish select element not found with ID:', 'day' + day + '_dish_' + index);
            return;
        }
        
        // Check if restaurantId is valid
        if (!restaurantId || restaurantId === '' || restaurantId === 'undefined' || restaurantId === null) {
            console.log('Invalid restaurant ID provided to loadDishesForRestaurant:', restaurantId);
            dishSelect.innerHTML = '<option value="">Select restaurant first</option>';
            dishSelect.style.display = 'block';
            
            // Clear any existing dynamic container (but keep the original dish container)
            let existingDynamicContainer = document.querySelector(`#day${day}_dish_container_${index} .dynamic-dishes`);
            if (existingDynamicContainer) {
                existingDynamicContainer.remove();
            }
            return;
        }
        
        dishSelect.innerHTML = '<option value="">Loading dishes...</option>';
        dishSelect.style.display = 'block'; // Make sure the select is visible
        
        // Clear any existing dynamic container (but keep the original dish container)
        let existingDynamicContainer = document.querySelector(`#day${day}_dish_container_${index} .dynamic-dishes`);
        if (existingDynamicContainer) {
            existingDynamicContainer.remove();
        }
        
        let url = '{{ route('fetch-meals-by-restaurant') }}?restaurant_id=' + encodeURIComponent(restaurantId);
        if (mealPeriod) {
            url += '&meal_period=' + encodeURIComponent(mealPeriod);
        }
        
        console.log('Fetching dishes from URL:', url);
        fetch(url)
            .then(response => response.json())
            .then(data => {
                console.log('Fetched dishes for restaurant:', restaurantId, 'meal period:', mealPeriod, 'Response:', data);
                dishSelect.innerHTML = '<option value="">Select Dish</option>';
                
                if (data.success && data.meals && data.meals.length > 0) {
                    // If we have meal data, show the dropdown
                    dishSelect.style.display = 'block';
                    console.log('Dishes loaded successfully, showing dropdown with', data.meals.length, 'options');
                    
                    // Using dropdown interface instead of buttons
                    
                    // Populate the select dropdown with dishes
                    data.meals.forEach(meal => {
                        const option = document.createElement('option');
                        option.value = meal.meal_id;
                        
                        let icon = '';
                        if (meal.type == 1) icon = '🍽️ ';
                        if (meal.type == 2) icon = '📋 ';
                        
                        option.textContent = `${icon}${meal.display_name || meal.name}`;
                        option.dataset.adultPrice = meal.adult_price || 0;
                        option.dataset.childPrice = meal.child_price || 0;
                        
                        // Debug logging
                        console.log('Meal data:', {
                            name: meal.name,
                            adult_price: meal.adult_price,
                            child_price: meal.child_price,
                            dataset_adultPrice: option.dataset.adultPrice,
                            dataset_childPrice: option.dataset.childPrice
                        });
                        
                        dishSelect.appendChild(option);
                    });
                } else {
                    // If API returns no dishes, create default options based on meal types
                    dishSelect.style.display = 'block';
                    console.log('No dishes from API, showing default options');
                    
                    const mealTypeSelect = document.getElementById('day' + day + '_meal_type_' + index);
                    if (mealTypeSelect && mealTypeSelect.selectedIndex > 0) {
                        const selectedMealType = mealTypeSelect.options[mealTypeSelect.selectedIndex].value;
                        
                        // Create default dish options based on meal type
                        const defaultDishes = [
                            { id: 'default_buffet', name: `${selectedMealType} Buffet`, type: 1 },
                            { id: 'default_set', name: `${selectedMealType} Set Menu`, type: 2 }
                        ];
                        
                        defaultDishes.forEach(dish => {
                            const option = document.createElement('option');
                            option.value = dish.id;
                            option.textContent = dish.name;
                            dishSelect.appendChild(option);
                        });
                    } else {
                        const option = document.createElement('option');
                        option.value = '';
                        option.textContent = data.message || 'No dishes available for this restaurant';
                        option.disabled = true;
                        dishSelect.appendChild(option);
                    }
                }
            })
            .catch(error => {
                console.error('Error loading dishes:', error);
                console.error('URL that failed:', url);
                dishSelect.innerHTML = '<option value="">Error loading dishes</option>';
                
                // Show user-friendly error message
                showNotification('Error loading dishes. Please try again.', 'error');
            });
    }
    
    // Function to update restaurant pricing display
    window.updateRestaurantPricing = function(day, index) {
        console.log(`=== UPDATING RESTAURANT PRICING: Day ${day}, Index ${index} ===`);
        
        const restaurantSelect = document.getElementById(`day${day}_restaurant_${index}`);
        const dishSelect = document.getElementById(`day${day}_dish_${index}`);
        const priceDisplay = document.getElementById(`day${day}_restaurant_${index}_price_display`);
        const restaurantNameDisplay = document.getElementById(`day${day}_restaurant_${index}_restaurant_name`);
        const pricingDetailsDisplay = document.getElementById(`day${day}_restaurant_${index}_pricing_details`);
        
        console.log('Elements found:', {
            restaurantSelect: !!restaurantSelect,
            dishSelect: !!dishSelect,
            priceDisplay: !!priceDisplay,
            restaurantNameDisplay: !!restaurantNameDisplay,
            pricingDetailsDisplay: !!pricingDetailsDisplay
        });
        
        if (!restaurantSelect || !priceDisplay) {
            console.log('Required elements not found for restaurant pricing update');
            return;
        }
        
        const selectedRestaurant = restaurantSelect.options[restaurantSelect.selectedIndex];
        const selectedDish = dishSelect ? dishSelect.options[dishSelect.selectedIndex] : null;
        
        console.log('Selected elements:', {
            restaurant: selectedRestaurant ? selectedRestaurant.text : 'None',
            dish: selectedDish ? selectedDish.text : 'None'
        });
        
        if (!selectedRestaurant || !selectedRestaurant.value) {
            console.log('No restaurant selected, hiding pricing');
            priceDisplay.style.display = 'none';
            // Update total display (restaurant is 0)
            updateRestaurantTotalDisplay(day, index);
            return;
        }
        
        // Update restaurant name
        if (restaurantNameDisplay) {
            restaurantNameDisplay.textContent = selectedRestaurant.text;
        }
        
        // Check if dish is selected (required for pricing)
        if (!selectedDish || !selectedDish.value) {
            console.log('No dish selected, showing info message');
            priceDisplay.style.display = 'block';
            if (pricingDetailsDisplay) {
                pricingDetailsDisplay.innerHTML = `
                    <div><strong>Restaurant Selected: ${selectedRestaurant.text}</strong></div>
                    <div class="text-muted">Please select a dish to see pricing information</div>
                `;
            }
            // Update total display (restaurant is 0, but transport might have value)
            updateRestaurantTotalDisplay(day, index);
            return;
        }
        
        // Get pricing data from the selected dish option
        let adultPrice = parseFloat(selectedDish.dataset.adultPrice) || 0;
        let childPrice = parseFloat(selectedDish.dataset.childPrice) || 0;
        
        console.log('Dish pricing data:', { 
            adultPrice, 
            childPrice,
            rawAdultPrice: selectedDish.dataset.adultPrice,
            rawChildPrice: selectedDish.dataset.childPrice,
            selectedDish: selectedDish
        });
        
        // Get current guest counts from the guest summary
        const guestSummaryElement = document.getElementById(`day${day}_restaurant_${index}_guest_summary`);
        if (!guestSummaryElement) {
            priceDisplay.style.display = 'none';
            return;
        }
        
        const guestText = guestSummaryElement.textContent;
        const adultsMatch = guestText.match(/(\d+)\s+adults/);
        const childrenMatch = guestText.match(/(\d+)\s+children/);
        
        const adults = adultsMatch ? parseInt(adultsMatch[1]) : 0;
        const children = childrenMatch ? parseInt(childrenMatch[1]) : 0;
        
        console.log('Guest counts:', { adults, children });
        
        if (adults > 0 || children > 0) {
            const adultTotal = adults * adultPrice;
            const childTotal = children * childPrice;
            const totalPrice = adultTotal + childTotal;
            
            priceDisplay.style.display = 'block';
            if (pricingDetailsDisplay) {
                pricingDetailsDisplay.innerHTML = `
                    <div><strong>Restaurant Selected: ${selectedRestaurant.text}</strong></div>
                    <div><strong>Dish: ${selectedDish.text}</strong></div>
                    ${adults > 0 ? `<div>${adults} Adults × $${adultPrice.toFixed(2)} = $${adultTotal.toFixed(2)}</div>` : ''}
                    ${children > 0 ? `<div>${children} Children × $${childPrice.toFixed(2)} = $${childTotal.toFixed(2)}</div>` : ''}
                    <div class="mt-2"><strong class="text-success">$${totalPrice.toFixed(2)}</strong></div>
                `;
            }
            
            // Update hidden total price field
            const totalPriceField = document.getElementById(`day${day}_restaurant_${index}_total_price`);
            if (totalPriceField) {
                totalPriceField.value = totalPrice.toFixed(2);
            }
            
            // Update total display (restaurant + transport)
            updateRestaurantTotalDisplay(day, index);
            
            console.log(`Restaurant pricing updated for day ${day}, index ${index}: Total: $${totalPrice}`);
        } else {
            priceDisplay.style.display = 'none';
            // Update total display even when no pricing
            updateRestaurantTotalDisplay(day, index);
        }
    }
    
    // Toggle between dish display modes (buttons/dropdown)
    function toggleDishDisplayMode(day, index, meals) {
        const dishSelect = document.getElementById('day' + day + '_dish_' + index);
        const dishContainer = document.getElementById('day' + day + '_dish_container_' + index);
        
        if (dishSelect.style.display === 'none') {
            // Switch to select dropdown mode
            dishSelect.style.display = 'block';
            if (dishContainer) dishContainer.style.display = 'none';
        } else {
            // Switch to buttons mode
            dishSelect.style.display = 'none';
            if (dishContainer) dishContainer.style.display = 'block';
        }
    }
    
