// Save service data to the backend
window.saveService = function(day, type) {
    // Get tour ID
    const tourId = window.currentTourId;
    if (!tourId) {
        showNotification('Tour ID not found. Please create a tour first.', 'error');
        return;
    }
    
    // Get agent ID
    const agentId = document.getElementById('agent_id').value;
    if (!agentId) {
        showNotification('Agent ID not found.', 'error');
        return;
    }
    
    // For entry_port, use the same format as edit.blade.php
    if (type === 'entry_port') {
        // Get customer info
        const customer_info = getCustomerInfo();
        
        // Get form data
        const pickupZoneId = document.querySelector(`select[name="day${day}_entry_pickup_zone_id"]`).value;
        const dropoffZoneId = document.querySelector(`select[name="day${day}_entry_dropoff_zone_id"]`).value;
        const pickupTime = document.querySelector(`select[name="day${day}_entry_pickup_time"]`).value;
        const pickupDate = document.querySelector(`input[name="day${day}_entry_pickup_date"]`).value;
        const vehicleId = document.querySelector(`select[name="day${day}_entry_vehicle_id"]`).value;
        const serviceType = document.querySelector(`select[name="day${day}_entry_service_type"]`).value;
        const passengers = document.getElementById(`day${day}_entry_passengers`).value;
        
        // Validate required fields
        if (!pickupZoneId || !dropoffZoneId || !pickupTime || !pickupDate || !vehicleId || !serviceType || !passengers) {
            showNotification('Please fill in all required fields for entry port service.', 'error');
            return;
        }
        
        // Get pickup and dropoff location names
        const pickupZoneSelect = document.querySelector(`select[name="day${day}_entry_pickup_zone_id"]`);
        const dropoffZoneSelect = document.querySelector(`select[name="day${day}_entry_dropoff_zone_id"]`);
        const pickupZoneName = pickupZoneSelect.options[pickupZoneSelect.selectedIndex]?.text || '';
        const dropoffZoneName = dropoffZoneSelect.options[dropoffZoneSelect.selectedIndex]?.text || '';
        
        // Get selected vehicle details
        const vehicleSelect = document.querySelector(`select[name="day${day}_entry_vehicle_id"]`);
        const selectedOption = vehicleSelect.options[vehicleSelect.selectedIndex];
        let vehicleData = {};
        if (selectedOption) {
            vehicleData = {
                image: selectedOption.dataset.image || "",
                dmc_id: selectedOption.dataset.dmcId || "",
                vehicle_name: selectedOption.dataset.vehicleName || selectedOption.text,
                vehicle_type: selectedOption.dataset.vehicleType || "",
                vehicle_model: selectedOption.dataset.vehicleModel || "",
                model_year: selectedOption.dataset.modelYear || null,
                seating_capacity: selectedOption.dataset.seatingcapacity || 0,
                city: "Singapore", // Default city
                country: "Singapore" // Default country
            };
        }
        
        // Get pricing data
        const totalPrice = document.getElementById(`day${day}_entry_total_price`).value || '0';
        
        // Build transport data in the same format as edit.blade.php
        const transportData = {
            fullName: customer_info.fullName,
            email: customer_info.email,
            phone: customer_info.phone,
            countryCode: customer_info.countryCode,
            address1: customer_info.address1,
            address2: customer_info.address2,
            state: customer_info.state,
            zip: customer_info.zip,
            specialRequests: customer_info.specialRequests,
            vehicles_id: vehicleId,
            image: vehicleData.image,
            dmc_id: vehicleData.dmc_id,
            vehicles_name: vehicleData.vehicle_name,
            Mode: "dmc",
            type: serviceType,
            entrypickup: pickupZoneName,
            entrydropoff: dropoffZoneName,
            bookingDate: pickupDate,
            pickupdate: pickupDate,
            entrytime: pickupTime,
            PickupPlaceid: pickupZoneId,
            DropoffPlaceid: dropoffZoneId,
            adults: parseInt(passengers),
            children: 0,
            totalPrice: parseFloat(totalPrice),
            Tax: 0,
            distance: 0,
            Night_Start_Time: null,
            Night_End_Time: null,
            city: vehicleData.city,
            country: vehicleData.country,
            id: `entry-${Date.now()}`,
            vehicle_type: vehicleData.vehicle_type,
            vehicle_model: vehicleData.vehicle_model,
            model_year: vehicleData.model_year,
            seating_capacity: vehicleData.seating_capacity,
            booking_id: null
        };
        
        console.log('Transport booking data:', transportData);
        
        // Create a form to submit the transport data (same as edit.blade.php)
        const form = document.createElement('form');
        form.method = 'POST';
        form.action = "{{ route('orders.transport.select') }}";
        
        // Add CSRF token
        const token = document.createElement('input');
        token.type = 'hidden';
        token.name = '_token';
        token.value = "{{ csrf_token() }}";
        form.appendChild(token);
        
        // Add the transport data as JSON
        const transportDataInput = document.createElement('input');
        transportDataInput.type = 'hidden';
        transportDataInput.name = 'transport_data';
        transportDataInput.value = JSON.stringify([transportData]); // Wrap in array
        form.appendChild(transportDataInput);
        
        // Add basic form fields
        const basicData = {
            tour_id: tourId,
            type: "entry_port",
            agent_id: agentId,
            pickup_zone_id: pickupZoneId,
            dropoff_zone_id: dropoffZoneId,
            pickup_time: pickupTime,
            pickup_date: pickupDate,
            vehicle_id: vehicleId,
            service_type: serviceType,
            passengers: passengers,
            country: "Singapore",
            city: "Singapore",
            transport_type: "entry_port"
        };
        
        for (const [key, value] of Object.entries(basicData)) {
            const input = document.createElement('input');
            input.type = 'hidden';
            input.name = key;
            input.value = value;
            form.appendChild(input);
        }
        
        document.body.appendChild(form);
        form.submit();
        
        // Show success message
        showNotification(`Entry port service booked successfully! From: ${pickupZoneName} To: ${dropoffZoneName}`, 'success');
        return;
    } 
    else if (type === 'exit_port') {
        // Similar to entry_port but for exit
        const customer_info = getCustomerInfo();
        
        const pickupZoneId = document.querySelector(`select[name="day${day}_exit_pickup_zone_id"]`).value;
        const dropoffZoneId = document.querySelector(`select[name="day${day}_exit_dropoff_zone_id"]`).value;
        const pickupTime = document.querySelector(`select[name="day${day}_exit_time"]`).value;
        const pickupDate = document.querySelector(`input[name="day${day}_exit_date"]`).value;
        const vehicleId = document.querySelector(`select[name="day${day}_exit_0_vehicle_id"]`).value;
        const serviceType = document.querySelector(`select[name="day${day}_exit_0_service_type"]`).value;
        
        if (!pickupZoneId || !dropoffZoneId || !pickupTime || !pickupDate || !vehicleId || !serviceType) {
            showNotification('Please fill in all required fields for exit port service.', 'error');
            return;
        }
        
        // Get location names
        const pickupZoneSelect = document.querySelector(`select[name="day${day}_exit_pickup_zone_id"]`);
        const dropoffZoneSelect = document.querySelector(`select[name="day${day}_exit_dropoff_zone_id"]`);
        const pickupZoneName = pickupZoneSelect.options[pickupZoneSelect.selectedIndex]?.text || '';
        const dropoffZoneName = dropoffZoneSelect.options[dropoffZoneSelect.selectedIndex]?.text || '';
        
        // Get vehicle details
        const vehicleSelect = document.querySelector(`select[name="day${day}_exit_0_vehicle_id"]`);
        const selectedOption = vehicleSelect.options[vehicleSelect.selectedIndex];
        let vehicleData = {};
        if (selectedOption) {
            vehicleData = {
                image: selectedOption.dataset.image || "",
                dmc_id: selectedOption.dataset.dmcId || "",
                vehicle_name: selectedOption.dataset.vehicleName || selectedOption.text,
                vehicle_type: selectedOption.dataset.vehicleType || "",
                vehicle_model: selectedOption.dataset.vehicleModel || "",
                model_year: selectedOption.dataset.modelYear || null,
                seating_capacity: selectedOption.dataset.seatingcapacity || 0,
                city: "Singapore",
                country: "Singapore"
            };
        }
        
        const totalPrice = document.getElementById(`day${day}_exit_total_price`).value || '0';
        
        const transportData = {
            fullName: customer_info.fullName,
            email: customer_info.email,
            phone: customer_info.phone,
            countryCode: customer_info.countryCode,
            address1: customer_info.address1,
            address2: customer_info.address2,
            state: customer_info.state,
            zip: customer_info.zip,
            specialRequests: customer_info.specialRequests,
            vehicles_id: vehicleId,
            image: vehicleData.image,
            dmc_id: vehicleData.dmc_id,
            vehicles_name: vehicleData.vehicle_name,
            Mode: "dmc",
            type: serviceType,
            entrypickup: pickupZoneName,
            entrydropoff: dropoffZoneName,
            bookingDate: pickupDate,
            pickupdate: pickupDate,
            entrytime: pickupTime,
            PickupPlaceid: pickupZoneId,
            DropoffPlaceid: dropoffZoneId,
            adults: parseInt(document.getElementById(`day${day}_exit_0_passengers`)?.value || 1),
            children: 0,
            totalPrice: parseFloat(totalPrice),
            Tax: 0,
            distance: 0,
            Night_Start_Time: null,
            Night_End_Time: null,
            city: vehicleData.city,
            country: vehicleData.country,
            id: `exit-${Date.now()}`,
            vehicle_type: vehicleData.vehicle_type,
            vehicle_model: vehicleData.vehicle_model,
            model_year: vehicleData.model_year,
            seating_capacity: vehicleData.seating_capacity,
            booking_id: null
        };
        
        // Submit using same method as entry_port
        const form = document.createElement('form');
        form.method = 'POST';
        form.action = "{{ route('orders.transport.select') }}";
        
        const token = document.createElement('input');
        token.type = 'hidden';
        token.name = '_token';
        token.value = "{{ csrf_token() }}";
        form.appendChild(token);
        
        const transportDataInput = document.createElement('input');
        transportDataInput.type = 'hidden';
        transportDataInput.name = 'transport_data';
        transportDataInput.value = JSON.stringify([transportData]);
        form.appendChild(transportDataInput);
        
        const basicData = {
            tour_id: tourId,
            type: "exit_port",
            agent_id: agentId,
            pickup_zone_id: pickupZoneId,
            dropoff_zone_id: dropoffZoneId,
            pickup_time: pickupTime,
            pickup_date: pickupDate,
            vehicle_id: vehicleId,
            service_type: serviceType,
            passengers: document.getElementById(`day${day}_exit_0_passengers`)?.value || 1,
            country: "Singapore",
            city: "Singapore",
            transport_type: "exit_port"
        };
        
        for (const [key, value] of Object.entries(basicData)) {
            const input = document.createElement('input');
            input.type = 'hidden';
            input.name = key;
            input.value = value;
            form.appendChild(input);
        }
        
        document.body.appendChild(form);
        form.submit();
        
        showNotification(`Exit port service booked successfully! From: ${pickupZoneName} To: ${dropoffZoneName}`, 'success');
        return;
    }
    else if (type === 'transport') {
        // Use same format as entry_port for transport services
        const customer_info = getCustomerInfo();
        
        const pickupZoneId = document.querySelector(`select[name="day${day}_transport_pickup_zone_id"]`).value;
        const dropoffZoneId = document.querySelector(`select[name="day${day}_transport_dropoff_zone_id"]`).value;
        const pickupTime = document.querySelector(`select[name="day${day}_transport_pickup_time"]`).value;
        const pickupDate = document.querySelector(`input[name="day${day}_transport_date"]`).value;
        const vehicleId = document.querySelector(`select[name="day${day}_transport_vehicle_id"]`).value;
        const serviceType = document.querySelector(`select[name="day${day}_transport_service_type"]`).value;
        
        // Check if point-to-point service type is selected
        const pointToPointRadio = document.querySelector(`input[name="day${day}_transport_service_type"][value="point_to_point"]`);
        const isPointToPoint = pointToPointRadio && pointToPointRadio.checked;
        
        // Get custom price for point-to-point services
        let customPrice = null;
        if (isPointToPoint) {
            const customPriceField = document.getElementById(`day${day}_transport_custom_price`);
            customPrice = customPriceField ? customPriceField.value : null;
            
            if (!customPrice || customPrice <= 0) {
                showNotification('Please enter a valid price for point-to-point service.', 'error');
                return;
            }
        }
        
        if (!pickupZoneId || !dropoffZoneId || !pickupTime || !pickupDate || !vehicleId || !serviceType) {
            showNotification('Please fill in all required fields for transport service.', 'error');
            return;
        }
        
        // Get location names
        const pickupZoneSelect = document.querySelector(`select[name="day${day}_transport_pickup_zone_id"]`);
        const dropoffZoneSelect = document.querySelector(`select[name="day${day}_transport_dropoff_zone_id"]`);
        const pickupZoneName = pickupZoneSelect.options[pickupZoneSelect.selectedIndex]?.text || '';
        const dropoffZoneName = dropoffZoneSelect.options[dropoffZoneSelect.selectedIndex]?.text || '';
        
        // Get vehicle details
        const vehicleSelect = document.querySelector(`select[name="day${day}_transport_vehicle_id"]`);
        const selectedOption = vehicleSelect.options[vehicleSelect.selectedIndex];
        let vehicleData = {};
        if (selectedOption) {
            vehicleData = {
                image: selectedOption.dataset.image || "",
                dmc_id: selectedOption.dataset.dmcId || "",
                vehicle_name: selectedOption.dataset.vehicleName || selectedOption.text,
                vehicle_type: selectedOption.dataset.vehicleType || "",
                vehicle_model: selectedOption.dataset.vehicleModel || "",
                model_year: selectedOption.dataset.modelYear || null,
                seating_capacity: selectedOption.dataset.seatingcapacity || 0,
                city: "Singapore",
                country: "Singapore"
            };
        }
        
        // Use custom price for point-to-point, otherwise use calculated total price
        const totalPrice = isPointToPoint && customPrice ? customPrice : (document.getElementById(`day${day}_transport_total_price`)?.value || '0');
        
        const transportData = {
            fullName: customer_info.fullName,
            email: customer_info.email,
            phone: customer_info.phone,
            countryCode: customer_info.countryCode,
            address1: customer_info.address1,
            address2: customer_info.address2,
            state: customer_info.state,
            zip: customer_info.zip,
            specialRequests: customer_info.specialRequests,
            vehicles_id: vehicleId,
            image: vehicleData.image,
            dmc_id: vehicleData.dmc_id,
            vehicles_name: vehicleData.vehicle_name,
            Mode: "dmc",
            type: serviceType,
            entrypickup: pickupZoneName,
            entrydropoff: dropoffZoneName,
            bookingDate: pickupDate,
            pickupdate: pickupDate,
            entrytime: pickupTime,
            PickupPlaceid: pickupZoneId,
            DropoffPlaceid: dropoffZoneId,
            adults: parseInt(document.getElementById(`day${day}_transport_passengers`)?.value || 1),
            children: 0,
            totalPrice: parseFloat(totalPrice),
            customPrice: isPointToPoint ? parseFloat(customPrice) : null,
            Tax: 0,
            distance: 0,
            Night_Start_Time: null,
            Night_End_Time: null,
            city: vehicleData.city,
            country: vehicleData.country,
            id: `transport-${Date.now()}`,
            vehicle_type: vehicleData.vehicle_type,
            vehicle_model: vehicleData.vehicle_model,
            model_year: vehicleData.model_year,
            seating_capacity: vehicleData.seating_capacity,
            booking_id: null
        };
        
        // Submit using same method as entry_port
        const form = document.createElement('form');
        form.method = 'POST';
        form.action = "{{ route('orders.transport.select') }}";
        
        const token = document.createElement('input');
        token.type = 'hidden';
        token.name = '_token';
        token.value = "{{ csrf_token() }}";
        form.appendChild(token);
        
        const transportDataInput = document.createElement('input');
        transportDataInput.type = 'hidden';
        transportDataInput.name = 'transport_data';
        transportDataInput.value = JSON.stringify([transportData]);
        form.appendChild(transportDataInput);
        
        const basicData = {
            tour_id: tourId,
            type: "transport",
            agent_id: agentId,
            pickup_zone_id: pickupZoneId,
            dropoff_zone_id: dropoffZoneId,
            pickup_time: pickupTime,
            pickup_date: pickupDate,
            vehicle_id: vehicleId,
            service_type: serviceType,
            passengers: document.getElementById(`day${day}_transport_passengers`)?.value || 1,
            country: "Singapore",
            city: "Singapore",
            transport_type: "transport"
        };
        
        for (const [key, value] of Object.entries(basicData)) {
            const input = document.createElement('input');
            input.type = 'hidden';
            input.name = key;
            input.value = value;
            form.appendChild(input);
        }
        
        document.body.appendChild(form);
        form.submit();
        
        showNotification(`Transport service booked successfully! From: ${pickupZoneName} To: ${dropoffZoneName}`, 'success');
        return;
    }
    
    // For other service types (guide, attraction, restaurant), use the save-service route
    else if (type === 'guide' || type === 'attraction' || type === 'restaurant') {
        let data = {};
        let section = '';
        
        if (type === 'guide') {
        section = 'guide';
        const guideId = document.querySelector(`select[name="day${day}_guide_1"]`).value;
        const packageType = document.querySelector(`select[name="day${day}_guide_1_package"]`).value;
        const pickupTime = document.querySelector(`input[name="day${day}_guide_1_pickup_time"]`).value;
        
        if (!guideId || !packageType || !pickupTime) {
            showNotification('Please fill in all required fields for guide service.', 'error');
            return;
        }
        
        data = {
            guide_id: guideId,
            package_type: packageType,
            pickup_time: pickupTime,
            day: day
        };
    }
    else if (type === 'attraction') {
        section = 'attraction';
        const attractionId = document.querySelector(`select[name="day${day}_attraction_1"]`).value;
        const ticketId = document.querySelector(`select[name="day${day}_attraction_1_ticket"]`).value;
        const timeSlot = document.querySelector(`select[name="day${day}_attraction_1_time"]`).value;
        
        if (!attractionId || !ticketId || !timeSlot) {
            showNotification('Please fill in all required fields for attraction service.', 'error');
            return;
        }
        
        // Get transfer options
        const transferRequired = document.getElementById(`day${day}_attraction_1_transfer_required`)?.value || 'No';
        let transferOptions = null;
        
        if (transferRequired === 'Yes') {
            const transferType = document.getElementById(`day${day}_attraction_1_transfer_type`)?.value || '';
            const transferWay = document.getElementById(`day${day}_attraction_1_transfer_way`)?.value || '';
            const transferVehicle = document.getElementById(`day${day}_attraction_1_transfer_vehicle`)?.value || '';
            const transferCost = parseFloat(document.getElementById(`day${day}_attraction_1_transfer_cost`)?.value || 0);
            const transferPickupLocation = document.getElementById(`day${day}_attraction_1_transfer_pickup_location`)?.value || '';
            
            // Get pickup location name
            let pickupLocationName = '';
            if (transferPickupLocation) {
                const pickupSelect = document.getElementById(`day${day}_attraction_1_transfer_pickup_location`);
                const selectedPickupOption = pickupSelect ? pickupSelect.options[pickupSelect.selectedIndex] : null;
                if (selectedPickupOption) {
                    pickupLocationName = selectedPickupOption.text || '';
                }
            }
            
            // Get vehicle details if vehicle is selected
            let vehicleDetails = null;
            if (transferVehicle) {
                const vehicleSelect = document.getElementById(`day${day}_attraction_1_transfer_vehicle`);
                const selectedVehicleOption = vehicleSelect ? vehicleSelect.options[vehicleSelect.selectedIndex] : null;
                if (selectedVehicleOption) {
                    vehicleDetails = {
                        vehicle_id: transferVehicle,
                        vehicle_name: selectedVehicleOption.getAttribute('data-vehicle-name') || '',
                        vehicle_type: selectedVehicleOption.getAttribute('data-vehicle-type') || '',
                        seating_capacity: selectedVehicleOption.getAttribute('data-seating-capacity') || '',
                        private_price: selectedVehicleOption.getAttribute('data-private-price') || '',
                        shared_price: selectedVehicleOption.getAttribute('data-shared-price') || ''
                    };
                }
            }
            
            transferOptions = {
                transfer_required: true,
                type: transferType,
                way: transferWay,
                vehicle_id: transferVehicle,
                vehicle_details: vehicleDetails,
                cost: transferCost,
                pickup_location_id: transferPickupLocation,
                pickup_location_name: pickupLocationName
            };
        }
        
        data = {
            attraction_id: attractionId,
            ticket_id: ticketId,
            time_slot: timeSlot,
            day: day,
            transfer_options: transferOptions
        };
    }
    else if (type === 'restaurant') {
        section = 'restaurant';
        const restaurantId = document.querySelector(`select[name="day${day}_restaurant_1"]`).value;
        const mealType = document.querySelector(`select[name="day${day}_meal_type_1"]`).value;
        const mealTime = document.querySelector(`select[name="day${day}_time_slot_1"]`).value;
        
        if (!restaurantId || !mealType || !mealTime) {
            showNotification('Please fill in all required fields for restaurant service.', 'error');
            return;
        }
        
        // Get transfer options
        const transferRequired = document.getElementById(`day${day}_restaurant_1_transfer_required`)?.value || 'No';
        let transferOptions = null;
        
        if (transferRequired === 'Yes') {
            const transferType = document.getElementById(`day${day}_restaurant_1_transfer_type`)?.value || '';
            const transferWay = document.getElementById(`day${day}_restaurant_1_transfer_way`)?.value || '';
            const transferVehicle = document.getElementById(`day${day}_restaurant_1_transfer_vehicle`)?.value || '';
            const transferCost = parseFloat(document.getElementById(`day${day}_restaurant_1_transfer_cost`)?.value || 0);
            const transferPickupLocation = document.getElementById(`day${day}_restaurant_1_transfer_pickup_location`)?.value || '';
            
            // Get pickup location name
            let pickupLocationName = '';
            if (transferPickupLocation) {
                const pickupSelect = document.getElementById(`day${day}_restaurant_1_transfer_pickup_location`);
                const selectedPickupOption = pickupSelect ? pickupSelect.options[pickupSelect.selectedIndex] : null;
                if (selectedPickupOption) {
                    pickupLocationName = selectedPickupOption.text || '';
                }
            }
            
            // Get vehicle details if vehicle is selected
            let vehicleDetails = null;
            if (transferVehicle) {
                const vehicleSelect = document.getElementById(`day${day}_restaurant_1_transfer_vehicle`);
                const selectedVehicleOption = vehicleSelect ? vehicleSelect.options[vehicleSelect.selectedIndex] : null;
                if (selectedVehicleOption) {
                    vehicleDetails = {
                        vehicle_id: transferVehicle,
                        vehicle_name: selectedVehicleOption.getAttribute('data-vehicle-name') || '',
                        vehicle_type: selectedVehicleOption.getAttribute('data-vehicle-type') || '',
                        seating_capacity: selectedVehicleOption.getAttribute('data-seating-capacity') || '',
                        private_price: selectedVehicleOption.getAttribute('data-private-price') || '',
                        shared_price: selectedVehicleOption.getAttribute('data-shared-price') || ''
                    };
                }
            }
            
            transferOptions = {
                transfer_required: true,
                type: transferType,
                way: transferWay,
                vehicle_id: transferVehicle,
                vehicle_details: vehicleDetails,
                cost: transferCost,
                pickup_location_id: transferPickupLocation,
                pickup_location_name: pickupLocationName
            };
        }
        
        data = {
            restaurant_id: restaurantId,
            meal_type: mealType,
            meal_time: mealTime,
            day: day,
            transfer_options: transferOptions
        };
    }
    
        // Use save-service route for these types
    const requestData = {
        agent_id: agentId,
        tour_id: tourId,
        type: type,
        data: data
    };
    
    // Show loading state
    const saveBtn = document.querySelector(`button[onclick="saveService(${day}, '${type}')"]`);
    const originalText = saveBtn.innerHTML;
    saveBtn.innerHTML = '<i class="ri-loader-4-line spin me-2"></i>Saving...';
    saveBtn.disabled = true;
    
         // Send data to backend
     fetch('{{ route("save-service") }}', {
        method: 'POST',
        headers: {
            'Content-Type': 'application/json',
            'X-CSRF-TOKEN': document.querySelector('meta[name="csrf-token"]').getAttribute('content')
        },
        body: JSON.stringify(requestData)
    })
    .then(response => response.json())
    .then(data => {
        if (data.success) {
            showNotification(`${type.replace('_', ' ').toUpperCase()} service saved successfully!`, 'success');
        } else {
            showNotification(data.message || 'Failed to save service.', 'error');
        }
        
        // Reset button state
        saveBtn.innerHTML = originalText;
        saveBtn.disabled = false;
    })
    .catch(error => {
        console.error('Error saving service:', error);
        showNotification('An error occurred while saving the service.', 'error');
        
        // Reset button state
        saveBtn.innerHTML = originalText;
        saveBtn.disabled = false;
    });
    }
}

// New functions for the search-based interface
 function searchVehicles(day, section, index=null) {
     console.log(`Searching vehicles for day ${day}, section ${section}`);
     
     // Check if Point-to-Point mode is enabled
     const isPointToPointElement = document.getElementById('is_point_to_point');
     const isPointToPoint = isPointToPointElement && isPointToPointElement.value === '1';
     
     // For entry/exit ports in Point-to-Point mode, use city-based search
     if (isPointToPoint && (section === 'entry' || section === 'exit')) {
         console.log(`Point-to-Point mode detected for ${section} port - using city-based vehicle search`);
         searchVehiclesPointToPoint(day, section);
         return;
     }
     
     // Normalize section name for element selectors
     // For transport_additional and transport_hourly, use 'transport' as the base section name
     // For transport_${index}_additional and transport_${index}_hourly, use 'transport_${index}' as the base section name
     let baseSection = section;
     if (section === 'transport_additional' || section === 'transport_hourly') {
         baseSection = 'transport';
     } else if (section.match(/^transport_\d+_(additional|hourly)$/)) {
         // Extract the index from section names like 'transport_2_additional' or 'transport_2_hourly'
         const match = section.match(/^transport_(\d+)_(additional|hourly)$/);
         if (match) {
             const index = match[1];
             baseSection = `transport_${index}`;
         }
     }
     
    // Handle entry/exit port field naming differently
    let pickupZoneSelect, dropoffZoneSelect, vehicleResultsDiv, vehicleSelect, serviceTypeSelect;
    
    if (section === 'entry' || section === 'exit') {
        // Entry/exit ports have different field naming patterns
        pickupZoneSelect = document.querySelector(`select[name="day${day}_${section}_pickup_zone_id"]`);
        dropoffZoneSelect = document.querySelector(`select[name="day${day}_${section}_dropoff_zone_id"]`);
        vehicleResultsDiv = document.getElementById(`day${day}_${section}_vehicle_results`);
        vehicleSelect = document.querySelector(`select[name="day${day}_${section}_0_vehicle_id"]`) || document.querySelector(`select[name="day${day}_${section}_vehicle_id"]`);
        serviceTypeSelect = document.querySelector(`select[name="day${day}_${section}_service_type"]`) || document.querySelector(`select[name="day${day}_${section}_0_service_type"]`);
    } else {
        // Regular transport sections
        pickupZoneSelect = document.querySelector(`select[name="day${day}_${section}_pickup_zone_id"]`);
        dropoffZoneSelect = document.querySelector(`select[name="day${day}_${section}_dropoff_zone_id"]`);
        vehicleResultsDiv = document.getElementById(`day${day}_${baseSection}_vehicle_results`);
        vehicleSelect = document.querySelector(`select[name="day${day}_${baseSection}_vehicle_id"]`);
        serviceTypeSelect = document.querySelector(`select[name="day${day}_${baseSection}_service_type"]`);
    }
     const searchBtn = document.getElementById(`day${day}_${section}_search_btn`);
     
     console.log('Elements found:', {
         pickupZoneSelect: !!pickupZoneSelect,
         dropoffZoneSelect: !!dropoffZoneSelect,
         vehicleResultsDiv: !!vehicleResultsDiv,
         vehicleSelect: !!vehicleSelect,
         serviceTypeSelect: !!serviceTypeSelect,
         searchBtn: !!searchBtn,
         baseSection: baseSection,
         section: section
     });
     
     if (vehicleSelect) {
         console.log('Vehicle select element:', vehicleSelect.name, vehicleSelect.id);
     } else {
         console.error('Vehicle select not found for day', day, 'section', section);
         console.log('Looking for selector: select[name="day${day}_${section}_vehicle_id"]');
     }

     // Check if search button is enabled
     if (!searchBtn || searchBtn.disabled) {
         alert('Please fill in all required fields before searching for vehicles');
         return;
     }

     // Check transport type to determine which endpoint to use
     const pointToPointRadio = document.querySelector(`input[name="day${day}_${baseSection}_service_type"][value="point_to_point"]`);
     const hourlyRadio = document.querySelector(`input[name="day${day}_${baseSection}_service_type"][value="hourly"]`);
     const localTransferRadio = document.querySelector(`input[name="day${day}_${baseSection}_service_type"][value="local_transfer"]`);
     
     let transportType = null;
     if (pointToPointRadio && pointToPointRadio.checked) {
         transportType = 'point_to_point';
     } else if (hourlyRadio && hourlyRadio.checked) {
         transportType = 'hourly';
     } else if (localTransferRadio && localTransferRadio.checked) {
         transportType = 'local_transfer';
     }
     
     console.log('Transport type detected:', transportType);
     console.log('Transport type radios found:', {
         pointToPointRadio: !!pointToPointRadio,
         hourlyRadio: !!hourlyRadio,
         localTransferRadio: !!localTransferRadio,
         baseSection: baseSection
     });

     // For point_to_point and hourly, use city-based endpoint
     if (transportType === 'point_to_point' || transportType === 'hourly') {
         // Get city from the transport city select for this day
         const transportCitySelect = document.getElementById(`day${day}_transport_city_${index}`);
         const exitport_city = document.getElementById("modal_exit_city");
         if ((!transportCitySelect || !transportCitySelect.value) && (!exitport_city || !exitport_city.value)) {
             alert('Please select a city in the transport section first');
             return;
         }
         
         const city = transportCitySelect.value || exitport_city.value;
         console.log('Using city-based endpoint for city:', city);

         // Show loading state
         searchBtn.innerHTML = '<i class="ri-loader-4-line spin me-2"></i>Searching...';
         searchBtn.disabled = true;

         fetch(`{{ url(route('fetch-vehicles-by-city-dmc')) }}?city=${encodeURIComponent(city)}`)
                             .then(response => response.json())
                .then(data => {
                 console.log('Vehicle search response (city-based):', data);
                 if (data.success && data.vehicles && data.vehicles.length > 0) {
                     // Filter vehicles for point-to-point and hourly transport types
                     let filteredVehicles = data.vehicles;
                     if (transportType === 'point_to_point' || transportType === 'hourly') {
                         console.log(`Filtering vehicles for ${transportType} - only showing vehicles where sharable=1 or sharable=3`);
                         filteredVehicles = data.vehicles.filter(vehicle => {
                             const sharable = parseInt(vehicle.sharable);
                             const isSharable = sharable === 1 || sharable === 3;
                             console.log(`Vehicle ${vehicle.vehicle_name}: sharable=${sharable}, filtered=${isSharable}`);
                             return isSharable;
                         });
                         console.log(`Filtered ${filteredVehicles.length} vehicles from ${data.vehicles.length} total vehicles for ${transportType}`);
                     }
                     
                     if (filteredVehicles.length > 0) {
                         // Populate vehicle dropdown
                         if (vehicleSelect) {
                             vehicleSelect.innerHTML = '<option value="">Choose your vehicle</option>';
                             filteredVehicles.forEach(vehicle => {
                                 const vehicleInfo = `${vehicle.vehicle_name} (${vehicle.vehicle_type}) - ${vehicle.seating_capacity} seats`;
                                 
                                 // Debug logging for vehicle data
                                 console.log('=== VEHICLE DATA DEBUG (city-based) ===');
                                 console.log('Vehicle:', vehicle);
                                 console.log('Private price:', vehicle.private_price);
                                 console.log('Shared price:', vehicle.shared_price);
                                 console.log('Sharable:', vehicle.sharable);
                                 
                                vehicleSelect.innerHTML += `<option value="${vehicle.vehicle_id}" 
                                     data-private-price="${vehicle.private_price || ''}" 
                                     data-shared-price="${vehicle.shared_price || ''}"
                                     data-service-type="${vehicle.service_type || ''}"
                                     data-cost-per-hour="${vehicle.cost_per_hour || ''}"
                                    data-sharable-cost-per-hour="${vehicle.sharable_cost_per_hour || ''}"
                                    data-seatingCapacity="${vehicle.seating_capacity || ''}"
                                    data-sharable="${vehicle.sharable || ''}"
                                    data-image="${vehicle.image || ''}">
                                     ${vehicleInfo}
                                 </option>`;
                             });
                         
                             // Enable the vehicle select
                            vehicleSelect.disabled = false;
                            console.log('Vehicle dropdown populated successfully (city-based)');
                        } else {
                            console.error('Vehicle select element not found!');
                        }
                    } else {
                        // No vehicles match the filter criteria
                        if (vehicleSelect) {
                            vehicleSelect.innerHTML = '<option value="">No suitable vehicles found</option>';
                            vehicleSelect.disabled = true;
                        }
                        console.log(`No vehicles found matching criteria for ${transportType} (sharable=1 or sharable=3)`);
                        alert(`No vehicles available for ${transportType} service. Please try a different city or contact support.`);
                        searchBtn.innerHTML = '<i class="ri-search-line me-2"></i>Search';
                        searchBtn.disabled = false;
                        return;
                    }

                    // Show results section
                    vehicleResultsDiv.style.display = 'block';
                    vehicleResultsDiv.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
                    
                    // Reset service type select and price display when vehicles are loaded
                    // For entry ports, use section_0; for exit ports, use section; for others, use baseSection
                    let sectionForUpdate;
                    if (section === 'entry') {
                        sectionForUpdate = 'entry_0';
                    } else if (section === 'exit') {
                        sectionForUpdate = 'exit';
                    } else {
                        sectionForUpdate = baseSection;
                    }
                    
                    // Show custom price field for point-to-point transport services
                    if (transportType === 'point_to_point' && baseSection.startsWith('transport')) {
                        const priceField = document.getElementById(`day${day}_${baseSection}_price_field`);
                        if (priceField) {
                            priceField.style.display = 'block';
                            console.log(`Showing custom price field for point-to-point transport: day${day}_${baseSection}_price_field`);
                        }
                    }
                    
                    
                    // Show custom price field and set service type to Private for entry ports when zone_on = 0
                    if (section === 'entry' || section.startsWith('entry_')) {
                        const dmcUser = @json($UserDmc);
                        const isZoneZero = dmcUser && dmcUser.zone_on == 0;
                        
                        if (isZoneZero) {
                            console.log(`Zone = 0 detected for entry port (${section}) - showing custom price field and setting service type to Private`);
                            
                            // For additional entry ports, use the section directly
                            let entrySection = sectionForUpdate;
                            if (section.startsWith('entry_')) {
                                entrySection = section;
                            }
                            
                            // Show custom price field
                            const entryPriceField = document.getElementById(`day${day}_${entrySection}_price_field`);
                            if (entryPriceField) {
                                entryPriceField.style.display = 'block';
                                console.log(`Showing custom price field for entry port (zone=0): day${day}_${entrySection}_price_field`);
                            }
                            
                            // Set service type to Private and make it readonly
                            const serviceTypeSelect = document.getElementById(`day${day}_${entrySection}_service_type`);
                            if (serviceTypeSelect) {
                                serviceTypeSelect.value = 'Private';
                                serviceTypeSelect.disabled = true;
                                serviceTypeSelect.style.backgroundColor = '#f8f9fa';
                                serviceTypeSelect.style.cursor = 'not-allowed';
                                console.log(`Set entry port service type to Private (readonly) for zone=0: day${day}_${entrySection}_service_type`);
                            }
                        }
                    }
                    
                    // Show custom price field and set service type to Private for exit ports when zone_on = 0
                    if (section === 'exit' || section.startsWith('exit_')) {
                        const dmcUser = @json($UserDmc);
                        const isZoneZero = dmcUser && dmcUser.zone_on == 0;
                        
                        if (isZoneZero) {
                            console.log(`Zone = 0 detected for exit port (${section}) - showing custom price field and setting service type to Private`);
                            
                            // For additional exit ports, use the section directly
                            let exitSection = sectionForUpdate;
                            if (section.startsWith('exit_')) {
                                exitSection = section;
                            }
                            
                            // Show custom price field
                            const exitPriceField = document.getElementById(`day${day}_${exitSection}_price_field`);
                            if (exitPriceField) {
                                exitPriceField.style.display = 'block';
                                console.log(`Showing custom price field for exit port (zone=0): day${day}_${exitSection}_price_field`);
                            }
                            
                            // Set service type to Private and make it readonly
                            const serviceTypeSelect = document.getElementById(`day${day}_${exitSection}_service_type`);
                            if (serviceTypeSelect) {
                                serviceTypeSelect.value = 'Private';
                                serviceTypeSelect.disabled = true;
                                serviceTypeSelect.style.backgroundColor = '#f8f9fa';
                                serviceTypeSelect.style.cursor = 'not-allowed';
                                console.log(`Set exit port service type to Private (readonly) for zone=0: day${day}_${exitSection}_service_type`);
                            }
                        }
                    }
                    
                    // Call updateVehicleDetails after the results section is shown
                    setTimeout(() => {
                        updateVehicleDetails(day, sectionForUpdate);
                    }, 100);

                     // Reset search button
                     searchBtn.innerHTML = '<i class="ri-search-line me-2"></i>Search';
                     searchBtn.disabled = false;
                     
                     console.log(`Populated ${filteredVehicles.length} vehicles in dropdown (city-based) for ${transportType}`);
                 } else {
                     alert('No vehicles available for this city. Please try a different city.');
                     searchBtn.innerHTML = '<i class="ri-search-line me-2"></i>Search';
                     searchBtn.disabled = false;
                 }
             })
             .catch(error => {
                 console.error('Error searching vehicles (city-based):', error);
                 alert('Error searching vehicles. Please try again.');
                 searchBtn.innerHTML = '<i class="ri-search-line me-2"></i>Search';
                 searchBtn.disabled = false;
             });
     } else {
         // For local_transfer, use zone-based endpoint (existing logic)
     if (!pickupZoneSelect || !dropoffZoneSelect || !pickupZoneSelect.value || !dropoffZoneSelect.value) {
         alert('Please select both pickup and dropoff zones');
         return;
     }

     const fromZoneId = pickupZoneSelect.value;
     const toZoneId = dropoffZoneSelect.value;

                 // Get location types from the selected options
        // For exit port: pickup should be attraction/restaurant, dropoff should be port
        let fromZoneType, toZoneType;
        
       // Get zone status from DMC user data
       const user_dmc = UserDmc;
       const zone_status = user_dmc ? user_dmc.zone_on : 1; // Default to 1 if no DMC data
       
       if (zone_status == 1) {
        if (section === 'exit') {
            // For exit port, pickup is typically attraction/restaurant, dropoff is port
            fromZoneType = pickupZoneSelect.options[pickupZoneSelect.selectedIndex]?.dataset?.type || 'attraction';
            toZoneType = dropoffZoneSelect.options[dropoffZoneSelect.selectedIndex]?.dataset?.type || 'port';
        } else {
            // For entry port and other sections, use original logic
            fromZoneType = pickupZoneSelect.options[pickupZoneSelect.selectedIndex]?.dataset?.type || 'port';
            toZoneType = dropoffZoneSelect.options[dropoffZoneSelect.selectedIndex]?.dataset?.type || 'attraction';
           }
       } else {
           // For zone_status != 1, don't use zone types
           fromZoneType = '';
           toZoneType = '';
        }
         
         // Get the actual zone IDs based on type
         let actualFromZoneId = fromZoneId;
         let actualToZoneId = toZoneId;
         
         // For ports, use port_id from data attribute
         if (fromZoneType === 'port') {
             actualFromZoneId = pickupZoneSelect.options[pickupZoneSelect.selectedIndex]?.dataset?.portId || fromZoneId;
         }
         
         if (toZoneType === 'port') {
             actualToZoneId = dropoffZoneSelect.options[dropoffZoneSelect.selectedIndex]?.dataset?.portId || toZoneId;
         }

         // Enhanced debugging for zone ID mapping
         console.log('=== ZONE ID MAPPING DEBUG ===');
         console.log('Section:', section);
         console.log('Original From Zone ID (pickup):', fromZoneId);
         console.log('Original To Zone ID (dropoff):', toZoneId);
         console.log('Actual From Zone ID:', actualFromZoneId);
         console.log('Actual To Zone ID:', actualToZoneId);
         console.log('From Zone Type:', fromZoneType);
         console.log('To Zone Type:', toZoneType);
         console.log('Pickup Zone Select Name:', pickupZoneSelect.name);
         console.log('Dropoff Zone Select Name:', dropoffZoneSelect.name);
         console.log('Pickup Zone Selected Text:', pickupZoneSelect.options[pickupZoneSelect.selectedIndex]?.text);
         console.log('Dropoff Zone Selected Text:', dropoffZoneSelect.options[dropoffZoneSelect.selectedIndex]?.text);
         console.log('==============================');

     // Show loading state
     searchBtn.innerHTML = 'Searching...';
     searchBtn.disabled = true;

                // Prepare request data with actual zone IDs and location types
        
        console.log('API Request Parameters:', {
            from_zone_id: actualFromZoneId,
            to_zone_id: actualToZoneId,
           from_zone_type: zone_status == 1 ? fromZoneType : '',
           to_zone_type: zone_status == 1 ? toZoneType : '',
           zone_status: zone_status,
            section: section,
            pickup_location: pickupZoneSelect.options[pickupZoneSelect.selectedIndex]?.text,
           dropoff_location: dropoffZoneSelect.options[dropoffZoneSelect.selectedIndex]?.text
       });

       fetch(`{{ url(route('fetch-vehicles-by-zones')) }}`, {
           method: 'POST',
           headers: {
               'Content-Type': 'application/json',
               'X-CSRF-TOKEN': document.querySelector('meta[name="csrf-token"]').getAttribute('content')
           },
           body: JSON.stringify({
               from_zone_id: actualFromZoneId,
               to_zone_id: actualToZoneId,
               from_zone_type: zone_status == 1 ? fromZoneType : '',
               to_zone_type: zone_status == 1 ? toZoneType : '',
               zone_status: zone_status
           })
       })
         .then(response => response.json())
         .then(data => {
                console.log('Vehicle search response (zone-based):', data);
             if (data.success && data.vehicles && data.vehicles.length > 0) {
                 // Remove duplicate vehicles by vehicle_id (backend should handle this, but add safety check)
                 const uniqueVehicles = [];
                 const seenVehicleIds = new Set();
                 
                 data.vehicles.forEach(vehicle => {
                     if (!seenVehicleIds.has(vehicle.vehicle_id)) {
                         seenVehicleIds.add(vehicle.vehicle_id);
                         uniqueVehicles.push(vehicle);
                     } else {
                         console.log(`Duplicate vehicle removed in frontend: ${vehicle.vehicle_name} (ID: ${vehicle.vehicle_id})`);
                     }
                 });
                 
                 // Populate vehicle dropdown
                 if (vehicleSelect) {
                     vehicleSelect.innerHTML = '<option value="">Choose your vehicle</option>';
                     
                     if (uniqueVehicles.length === 0) {
                         vehicleSelect.innerHTML = '<option value="">No vehicles with prices available</option>';
                         vehicleSelect.disabled = true;
                         console.log('No vehicles with prices found');
                     } else {
                         uniqueVehicles.forEach(vehicle => {
                             const vehicleInfo = `${vehicle.vehicle_name} (${vehicle.vehicle_type}) - ${vehicle.seating_capacity} seats`;
                             
                             // Debug logging for vehicle data
                            console.log('=== VEHICLE DATA DEBUG (zone-based) ===');
                         console.log('Vehicle:', vehicle);
                         console.log('Private price:', vehicle.private_price);
                         console.log('Shared price:', vehicle.shared_price);
                         console.log('Mapping ID:', vehicle.mapping_id);
                         
                        vehicleSelect.innerHTML += `<option value="${vehicle.vehicle_id}" 
                             data-private-price="${vehicle.private_price || ''}" 
                             data-shared-price="${vehicle.shared_price || ''}"
                             data-service-type="${vehicle.service_type || ''}"
                             data-mapping-id="${vehicle.mapping_id || ''}"
                            data-seatingCapacity="${vehicle.seating_capacity || ''}"
                            data-sharable="${vehicle.sharable || ''}"
                            data-image="${vehicle.image || ''}">
                             ${vehicleInfo}
                         </option>`;
                         });
                     }
                     
                     // Enable the vehicle select
                     vehicleSelect.disabled = false;
                        console.log('Vehicle dropdown populated successfully (zone-based)');
                 } else {
                     console.error('Vehicle select element not found!');
                 }

                 // Show results section
                 vehicleResultsDiv.style.display = 'block';
                 vehicleResultsDiv.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
                 
                 // Reset service type select and price display when vehicles are loaded
                 // For entry ports, use section_0; for exit ports, use section; for others, use baseSection
                 let sectionForUpdate;
                 if (section === 'entry') {
                     sectionForUpdate = 'entry_0';
                 } else if (section === 'exit') {
                     sectionForUpdate = 'exit';
                 } else {
                     sectionForUpdate = baseSection;
                 }
                 
                 // Call updateVehicleDetails after the results section is shown
                 setTimeout(() => {
                     updateVehicleDetails(day, sectionForUpdate);
                 }, 100);

                 // Reset search button
                 searchBtn.innerHTML = '<i class="ri-search-line me-2"></i>Search';
                 searchBtn.disabled = false;
                 
                    console.log(`Populated ${uniqueVehicles.length} unique vehicles in dropdown (zone-based)`);
                    
                    // Add info message for exit port to indicate bidirectional search
                    if (section === 'exit') {
                        const existingMessage = vehicleResultsDiv.querySelector('.bidirectional-message');
                        if (existingMessage) {
                            existingMessage.remove();
                        }
                        
                        const messageDiv = document.createElement('div');
                        messageDiv.className = 'alert alert-success bidirectional-message mt-2';
                        messageDiv.innerHTML = `
                            <i class="ri-check-line me-2"></i>
                            <strong>Bidirectional Route:</strong> These vehicles are available for both directions of this route.
                        `;
                        vehicleResultsDiv.insertBefore(messageDiv, vehicleResultsDiv.firstChild);
                    }
             } else {
                 alert('No vehicles available for this route. Please try different zones.');
                 searchBtn.innerHTML = '<i class="ri-search-line me-2"></i>Search';
                 searchBtn.disabled = false;
             }
         })
         .catch(error => {
                 console.error('Error searching vehicles (zone-based):', error);
             alert('Error searching vehicles. Please try again.');
             searchBtn.innerHTML = '<i class="ri-search-line me-2"></i>Search';
             searchBtn.disabled = false;
         });
 }
 }

  function clearDropoffZone(day, section) {
     const dropoffZoneSelect = document.querySelector(`select[name="day${day}_${section}_dropoff_zone_id"]`);
     const vehicleResultsDiv = document.getElementById(`day${day}_${section}_vehicle_results`);
     const searchBtn = document.getElementById(`day${day}_${section}_search_btn`);

     if (dropoffZoneSelect) {
         dropoffZoneSelect.value = '';
         dropoffZoneSelect.innerHTML = '<option value="">Select pickup zone first</option>';
         dropoffZoneSelect.disabled = true;
     }

     if (vehicleResultsDiv) {
         vehicleResultsDiv.style.display = 'none';
     }

     if (searchBtn) {
         searchBtn.disabled = true;
         searchBtn.classList.remove('btn-primary');
         searchBtn.classList.add('btn-secondary');
     }
     
     // Check if search button should be enabled
     enableSearchButton(day, section);
 }

 // Update the existing loadDropoffZones function for the new interface
 function loadDropoffZonesNew(day, section) {
     const pickupZoneSelect = document.querySelector(`select[name="day${day}_${section}_pickup_zone_id"]`);
     const dropoffZoneSelect = document.querySelector(`select[name="day${day}_${section}_dropoff_zone_id"]`);
     const searchBtn = document.getElementById(`day${day}_${section}_search_btn`);
     const vehicleResultsDiv = document.getElementById(`day${day}_${section}_vehicle_results`);

     if (!pickupZoneSelect || !dropoffZoneSelect) return;

     const pickupZoneId = pickupZoneSelect.value;

     if (pickupZoneId) {
         // Check if this is an entry port dropoff (should show zone-assigned locations, not zones)
         if (section === 'entry' && dropoffZoneSelect.name.includes('_entry_dropoff_zone_id')) {
             // For entry port dropoff, populate with zone-assigned locations
             console.log('Populating entry port dropoff with zone-assigned locations (new interface)');
             dropoffZoneSelect.innerHTML = '<option value="">Loading locations...</option>';
             
             fetch(`{{ route('fetch-zone-assigned-locations') }}`)
                                 .then(response => response.json())
                .then(data => {
                     if (data.success && data.locations) {
                         console.log('Zone-assigned locations fetched (new interface):', data.locations.length);
                         dropoffZoneSelect.innerHTML = '<option value="">Select dropoff location</option>';
                         
                         data.locations.forEach(location => {
                             const option = document.createElement('option');
                             option.value = location.id;
                             option.textContent = `${location.name} (${location.type}) - ${location.location}`;
                             option.dataset.type = location.type;
                             option.dataset.latitude = location.latitude || '';
                             option.dataset.longitude = location.longitude || '';
                             dropoffZoneSelect.appendChild(option);
                         });
                         
                         dropoffZoneSelect.disabled = false;
                     } else {
                         dropoffZoneSelect.innerHTML = '<option value="">No locations available</option>';
                         dropoffZoneSelect.disabled = true;
                     }
                 })
                 .catch(error => {
                     console.error('Error fetching zone-assigned locations (new interface):', error);
                     dropoffZoneSelect.innerHTML = '<option value="">Error loading locations</option>';
                     dropoffZoneSelect.disabled = true;
                 });
         } else {
             // For all other dropoffs, use zones (city will come from transport section)
         const transportCitySelect = document.querySelector('.transport-city-select');
         const city = transportCitySelect ? transportCitySelect.value : '';
         
         fetch(`{{ route('fetch-zones-by-dmc') }}?city=${encodeURIComponent(city)}`)
             .then(response => response.json())
             .then(data => {
                 if (data.success && data.zones) {
                     dropoffZoneSelect.innerHTML = '<option value="">Select dropoff zone</option>';

                     // Show all zones except the selected pickup zone
                     data.zones.forEach(zone => {
                         if (zone.zone_id !== pickupZoneId) {
                             dropoffZoneSelect.innerHTML += `<option value="${zone.zone_id}">${zone.zone_name} (${zone.zone_type})</option>`;
                         }
                     });

                     dropoffZoneSelect.disabled = false;
                 }
             })
             .catch(error => {
                 console.error('Error fetching dropoff zones:', error);
             });
         }
     } else {
         dropoffZoneSelect.innerHTML = '<option value="">Select pickup zone first</option>';
         dropoffZoneSelect.disabled = true;
         if (searchBtn) searchBtn.disabled = true;
         if (vehicleResultsDiv) vehicleResultsDiv.style.display = 'none';
     }
 }

 // Update dropdown change handlers for new interface
 function setupNewTransportationHandlers() {
     console.log('Setting up transportation handlers');
     
     // Setup pickup zone change handlers using event delegation
     document.addEventListener('change', function(event) {
         if (event.target.classList.contains('pickup-zone-select')) {
             console.log('Pickup zone change detected:', event.target.name);
             const [day, section] = extractDayAndSection(event.target.name);
             console.log('Extracted day:', day, 'section:', section);
             if (day && section) {
                 handlePickupZoneChange(day, section);
             }
         }
     });

     // Setup dropoff zone change handlers
     const dropoffZoneSelects = document.querySelectorAll('.dropoff-zone-select');
     dropoffZoneSelects.forEach(select => {
         select.addEventListener('change', function() {
             const [day, section] = extractDayAndSection(this.name);
             const searchBtn = document.getElementById(`day${day}_${section}_search_btn`);
             
             if (this.value && searchBtn) {
                 searchBtn.disabled = false;
             } else if (searchBtn) {
                 searchBtn.disabled = true;
             }
         });
     });
 }

 function extractDayAndSection(fieldName) {
     // Extract day and section from field names like "day1_entry_pickup_zone_id"
     // We want to extract: day=1, section=entry from "day1_entry_pickup_zone_id"
     const match = fieldName.match(/day(\d+)_(\w+)_/);
     if (match) {
         const day = match[1];
         // Extract the section (entry, exit, transport) from the field name
         // Use a more specific regex to get just the section part
         const sectionMatch = fieldName.match(/day\d+_([^_]+)_/);
         const section = sectionMatch ? sectionMatch[1] : null;
         console.log(`Extracted from "${fieldName}": day=${day}, section=${section}`);
         return [day, section];
     }
     console.log(`No match found for field name: "${fieldName}"`);
     return [null, null];
 }
</script>
@endsection

